using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using System.Text;

var sb = new StringBuilder();
var active = EditorSceneManager.GetActiveScene();
sb.AppendLine($"activeScene: {active.path}  loaded={active.isLoaded} dirty={active.isDirty} rootCount={active.rootCount}");

foreach (var go in active.GetRootGameObjects())
{
    var comps = go.GetComponents<Component>();
    var names = new StringBuilder();
    foreach (var c in comps) names.Append(c == null ? "<missing>" : c.GetType().Name).Append(',');
    sb.AppendLine($"  root: {go.name}  active={go.activeSelf}  comps={names}");
}

sb.AppendLine("--- scenes in project ---");
foreach (var guid in AssetDatabase.FindAssets("t:Scene"))
{
    var p = AssetDatabase.GUIDToAssetPath(guid);
    sb.AppendLine("  " + p);
}

sb.AppendLine("--- render pipeline ---");
var rp = UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline;
sb.AppendLine("  srp=" + (rp == null ? "null(Built-in)" : rp.GetType().Name + " : " + rp.name));

return sb.ToString();

