namespace ThreeCup.GrayBox
{
    public enum PlayerSide
    {
        Left,
        Right
    }

    public enum ControlMode
    {
        SinglePlayer,
        TwoPlayer
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    [RequireComponent(typeof(Rigidbody2D))]
    public sealed class PlayerMotor2D : MonoBehaviour
    {
        [Header("Identity")]
        [SerializeField] PlayerSide side = PlayerSide.Left;

        [Header("Movement")]
        [SerializeField] float moveSpeed = 5.5f;
        [SerializeField] float jumpVelocity = 10.5f;

        [Header("Fall Recovery")]
        [SerializeField] float fallRespawnY = -6f;

        [Header("Ground Check")]
        [SerializeField] LayerMask groundMask = ~0;
        [SerializeField] float groundRayLength = 0.1f;

        public PlayerSide Side => side;
        public bool Grounded { get; private set; }
        public int RespawnCount { get; private set; }
        public Vector2 SafePoint => safePoint;

        Rigidbody2D body;
        Collider2D bodyCollider;
        InputRouter router;
        Vector2 safePoint;
        float horizontalInput;
        bool jumpRequested;

        void Awake()
        {
            body = GetComponent<Rigidbody2D>();
            bodyCollider = GetComponent<Collider2D>();
            safePoint = body.position;
        }

        void Update()
        {
            if (router == null) router = FindObjectOfType<InputRouter>();
            if (router == null)
            {
                horizontalInput = 0f;
                jumpRequested = false;
                return;
            }

            horizontalInput = router.GetHorizontal(side);
            if (router.GetJumpDown(side)) jumpRequested = true;
        }

        void FixedUpdate()
        {
            Grounded = CheckGrounded();

            Vector2 velocity = body.velocity;
            velocity.x = horizontalInput * moveSpeed;
            if (jumpRequested && Grounded) velocity.y = jumpVelocity;
            jumpRequested = false;
            body.velocity = velocity;

            // The last spot we stood still on is the safest place to come back to.
            if (Grounded && Mathf.Abs(velocity.y) < 0.6f) safePoint = body.position;

            if (body.position.y < fallRespawnY) Respawn();
        }

        /// <summary>Ray starts just below the collider so it cannot hit ourselves.</summary>
        bool CheckGrounded()
        {
            Bounds bounds = bodyCollider.bounds;
            float originY = bounds.min.y - 0.02f;
            float inset = 0.05f;

            if (Physics2D.Raycast(new Vector2(bounds.center.x, originY), Vector2.down, groundRayLength, groundMask)) return true;
            if (Physics2D.Raycast(new Vector2(bounds.min.x + inset, originY), Vector2.down, groundRayLength, groundMask)) return true;
            if (Physics2D.Raycast(new Vector2(bounds.max.x - inset, originY), Vector2.down, groundRayLength, groundMask)) return true;
            return false;
        }

        void Respawn()
        {
            body.velocity = Vector2.zero;
            body.position = safePoint;
            transform.position = safePoint;
            RespawnCount++;
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// Owns the only input state in the prototype. Characters never read keys directly,
    /// so switching the controlled side can never leak into rendering or movement rules.
    /// </summary>
    public sealed class InputRouter : MonoBehaviour
    {
        [SerializeField] ControlMode mode = ControlMode.SinglePlayer;
        [SerializeField] PlayerSide activeSide = PlayerSide.Left;

        public ControlMode Mode => mode;
        public PlayerSide ActiveSide => activeSide;

        void Update()
        {
            if (mode != ControlMode.SinglePlayer) return;
            if (Input.GetMouseButtonDown(0)) ToggleActiveSide();
        }

        public void SetMode(ControlMode value) => mode = value;

        public void SetActiveSide(PlayerSide value) => activeSide = value;

        public void ToggleActiveSide() =>
            activeSide = activeSide == PlayerSide.Left ? PlayerSide.Right : PlayerSide.Left;

        public bool IsControlled(PlayerSide side) =>
            mode == ControlMode.TwoPlayer || side == activeSide;

        public float GetHorizontal(PlayerSide side)
        {
            if (!IsControlled(side)) return 0f;

            if (mode == ControlMode.TwoPlayer)
            {
                return side == PlayerSide.Left
                    ? Axis(KeyCode.A, KeyCode.D)
                    : Axis(KeyCode.LeftArrow, KeyCode.RightArrow);
            }

            // Single player: only one character listens, so both key sets may drive it.
            float wasd = Axis(KeyCode.A, KeyCode.D);
            return Mathf.Approximately(wasd, 0f) ? Axis(KeyCode.LeftArrow, KeyCode.RightArrow) : wasd;
        }

        public bool GetJumpDown(PlayerSide side)
        {
            if (!IsControlled(side)) return false;

            if (mode == ControlMode.TwoPlayer)
            {
                return side == PlayerSide.Left
                    ? Input.GetKeyDown(KeyCode.W)
                    : Input.GetKeyDown(KeyCode.UpArrow);
            }

            return Input.GetKeyDown(KeyCode.W)
                || Input.GetKeyDown(KeyCode.UpArrow)
                || Input.GetKeyDown(KeyCode.Space);
        }

        static float Axis(KeyCode negative, KeyCode positive) =>
            (Input.GetKey(positive) ? 1f : 0f) - (Input.GetKey(negative) ? 1f : 0f);
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// A hole punched in the fog. Follows its owner, displaced by an offset that is
    /// configured per window so the two sides do not have to be mirrored exactly.
    /// </summary>
    [ExecuteAlways]
    public sealed class VisionWindow : MonoBehaviour
    {
        [SerializeField] Transform owner;
        [SerializeField] Vector2 offset = new Vector2(8f, 0f);

        public Transform Owner => owner;
        public Vector2 Offset => offset;

        void LateUpdate() => Refresh();

        void OnValidate() => Refresh();

        public void Configure(Transform newOwner, Vector2 newOffset)
        {
            owner = newOwner;
            offset = newOffset;
            Refresh();
        }

        public void Refresh()
        {
            if (owner == null) return;

            Vector2 target = (Vector2)owner.position + offset;
            if (((Vector2)transform.position - target).sqrMagnitude < 0.000001f) return;

            transform.position = new Vector3(target.x, target.y, 0f);
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    [RequireComponent(typeof(Collider2D))]
    public sealed class Portal : MonoBehaviour
    {
        [SerializeField] PlayerSide side = PlayerSide.Left;

        public PlayerSide Side => side;
        public bool Occupied { get; private set; }

        void Reset()
        {
            var col = GetComponent<Collider2D>();
            if (col != null) col.isTrigger = true;
        }

        void OnTriggerEnter2D(Collider2D other)
        {
            if (IsOwnCharacter(other)) Occupied = true;
        }

        void OnTriggerExit2D(Collider2D other)
        {
            if (IsOwnCharacter(other)) Occupied = false;
        }

        bool IsOwnCharacter(Collider2D other)
        {
            var motor = other.GetComponent<PlayerMotor2D>();
            return motor != null && motor.Side == side;
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// Clearing a level means both characters stand in their own portal at the same time.
    /// </summary>
    public sealed class WinChecker : MonoBehaviour
    {
        [SerializeField] Portal leftPortal;
        [SerializeField] Portal rightPortal;
        [SerializeField] float requiredSeconds = 0.5f;

        public bool Completed { get; private set; }
        public float HeldSeconds => heldSeconds;

        float heldSeconds;

        public void Configure(Portal left, Portal right) 
        {
            leftPortal = left;
            rightPortal = right;
        }

        void Update()
        {
            if (Completed) return;

            bool bothInside = leftPortal != null && rightPortal != null &&
                              leftPortal.Occupied && rightPortal.Occupied;

            heldSeconds = bothInside ? heldSeconds + Time.deltaTime : 0f;
            if (heldSeconds < requiredSeconds) return;

            Completed = true;
            Debug.Log("[GrayBox] 通关：两名角色同时站在各自的传送门内");
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>Dims the character that is not currently taking input.</summary>
    [RequireComponent(typeof(SpriteRenderer))]
    public sealed class PlayerVisual : MonoBehaviour
    {
        [SerializeField] PlayerSide side = PlayerSide.Left;
        [SerializeField] Color activeColor = Color.white;
        [SerializeField] Color inactiveColor = new Color(0.35f, 0.35f, 0.35f, 1f);

        SpriteRenderer target;
        InputRouter router;

        public void Configure(PlayerSide newSide, Color active)
        {
            side = newSide;
            activeColor = active;
        }

        void Awake() => target = GetComponent<SpriteRenderer>();

        void Update()
        {
            if (target == null) target = GetComponent<SpriteRenderer>();
            if (router == null) router = FindObjectOfType<InputRouter>();
            if (router == null) return;

            target.color = router.IsControlled(side) ? activeColor : inactiveColor;
        }
    }
}

