using System.IO;
using UnityEditor;
using UnityEngine;

const string folder = "Assets/Art/GrayBox";
if (!AssetDatabase.IsValidFolder("Assets/Art")) AssetDatabase.CreateFolder("Assets", "Art");
if (!AssetDatabase.IsValidFolder(folder)) AssetDatabase.CreateFolder("Assets/Art", "GrayBox");

string pngPath = folder + "/White4x4.png";
if (!File.Exists(pngPath))
{
    var tex = new Texture2D(4, 4, TextureFormat.RGBA32, false);
    var pixels = new Color32[16];
    for (int i = 0; i < pixels.Length; i++) pixels[i] = new Color32(255, 255, 255, 255);
    tex.SetPixels32(pixels);
    tex.Apply();
    File.WriteAllBytes(pngPath, tex.EncodeToPNG());
    Object.DestroyImmediate(tex);
    AssetDatabase.ImportAsset(pngPath, ImportAssetOptions.ForceSynchronousImport);
}

var importer = (TextureImporter)AssetImporter.GetAtPath(pngPath);
importer.textureType = TextureImporterType.Sprite;
importer.spriteImportMode = SpriteImportMode.Single;
importer.spritePixelsPerUnit = 4f;
importer.filterMode = FilterMode.Point;
importer.textureCompression = TextureImporterCompression.Uncompressed;
importer.mipmapEnabled = false;
importer.alphaIsTransparency = true;
importer.wrapMode = TextureWrapMode.Clamp;
importer.SaveAndReimport();

string matPath = folder + "/PlayerNoFriction.physicsMaterial2D";
if (AssetDatabase.LoadAssetAtPath<PhysicsMaterial2D>(matPath) == null)
{
    var mat = new PhysicsMaterial2D("PlayerNoFriction") { friction = 0f, bounciness = 0f };
    AssetDatabase.CreateAsset(mat, matPath);
}

AssetDatabase.SaveAssets();
var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(pngPath);
return sprite == null
    ? "SPRITE_NOT_FOUND"
    : $"sprite={sprite.name} rect={sprite.rect.size} ppu={sprite.pixelsPerUnit} bounds={sprite.bounds.size}";

