using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using ThreeCup.GrayBox;
using System.Text;

Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/GrayBox/White4x4.png");
PhysicsMaterial2D noFriction = AssetDatabase.LoadAssetAtPath<PhysicsMaterial2D>("Assets/Art/GrayBox/PlayerNoFriction.physicsMaterial2D");
if (sprite == null) return "SPRITE_MISSING";

var old = GameObject.Find("GrayBox");
if (old != null) UnityEngine.Object.DestroyImmediate(old);

var root = new GameObject("GrayBox");

GameObject MakeQuad(string name, Transform parent, Vector2 center, Vector2 size, Color color, int order)
{
    var go = new GameObject(name);
    go.transform.SetParent(parent, false);
    go.transform.position = new Vector3(center.x, center.y, 0f);
    go.transform.localScale = new Vector3(size.x, size.y, 1f);
    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = color;
    sr.sortingOrder = order;
    return go;
}

// ---------- camera ----------
var camGo = GameObject.Find("Main Camera");
Camera cam = camGo != null ? camGo.GetComponent<Camera>() : new GameObject("Main Camera").AddComponent<Camera>();
cam.orthographic = true;
cam.orthographicSize = 4.5f;
cam.transform.position = new Vector3(0f, 0f, -10f);
cam.transform.rotation = Quaternion.identity;
cam.clearFlags = CameraClearFlags.SolidColor;
cam.backgroundColor = new Color(0.05f, 0.05f, 0.07f, 1f);

// ---------- terrain (top surface at y = -3) ----------
var terrain = new GameObject("Terrain").transform;
terrain.SetParent(root.transform, false);

const float groundTop = -3f;
const float platformHeight = 0.8f;
Color platformColor = new Color(0.42f, 0.45f, 0.52f, 1f);

// [name, minX, maxX]  - the 1 unit gaps are the pits.
var platforms = new (string name, float minX, float maxX)[]
{
    ("Plat_L1", -8.0f, -4.0f),
    ("Plat_L2", -3.0f,  0.0f),
    ("Plat_R1",  0.0f,  3.0f),
    ("Plat_R2",  4.0f,  8.0f),
};

foreach (var p in platforms)
{
    float w = p.maxX - p.minX;
    var go = MakeQuad(p.name, terrain, new Vector2((p.minX + p.maxX) * 0.5f, groundTop - platformHeight * 0.5f),
                      new Vector2(w, platformHeight), platformColor, 0);
    var col = go.AddComponent<BoxCollider2D>();
    col.size = Vector2.one;
}

// ---------- portals ----------
var portalRoot = new GameObject("Portals").transform;
portalRoot.SetParent(root.transform, false);

Portal MakePortal(string name, float x, PlayerSide side, Color color)
{
    var go = MakeQuad(name, portalRoot, new Vector2(x, groundTop + 0.9f), new Vector2(1.0f, 1.8f), color, 5);
    var col = go.AddComponent<BoxCollider2D>();
    col.isTrigger = true;
    col.size = Vector2.one;
    var portal = go.AddComponent<Portal>();
    portal.Configure(side);
    return portal;
}

var leftPortal = MakePortal("Portal_Left", -1.0f, PlayerSide.Left, new Color(0.25f, 0.85f, 0.55f, 1f));
var rightPortal = MakePortal("Portal_Right", 1.0f, PlayerSide.Right, new Color(0.85f, 0.55f, 0.25f, 1f));

// ---------- players ----------
var playerRoot = new GameObject("Players").transform;
playerRoot.SetParent(root.transform, false);

GameObject MakePlayer(string name, Vector2 spawn, PlayerSide side, Color color)
{
    var go = new GameObject(name);
    go.transform.SetParent(playerRoot, false);
    go.transform.position = spawn;
    go.transform.localScale = Vector3.one * 0.8f;

    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = color;
    sr.sortingOrder = 20;

    var col = go.AddComponent<BoxCollider2D>();
    col.size = Vector2.one;
    col.sharedMaterial = noFriction;

    var body = go.AddComponent<Rigidbody2D>();
    body.gravityScale = 3f;
    body.constraints = RigidbodyConstraints2D.FreezeRotation;
    body.interpolation = RigidbodyInterpolation2D.Interpolate;
    body.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
    body.sharedMaterial = noFriction;

    var motor = go.AddComponent<PlayerMotor2D>();
    motor.Configure(side);

    var visual = go.AddComponent<PlayerVisual>();
    visual.Configure(side, color);
    return go;
}

var leftChar = MakePlayer("Player_Left", new Vector2(-6.5f, -2.4f), PlayerSide.Left, new Color(0.35f, 0.75f, 1f, 1f));
var rightChar = MakePlayer("Player_Right", new Vector2(6.5f, -2.4f), PlayerSide.Right, new Color(1f, 0.72f, 0.35f, 1f));

// ---------- fog ----------
var visionRoot = new GameObject("Vision").transform;
visionRoot.SetParent(root.transform, false);

var fog = MakeQuad("Fog", visionRoot, Vector2.zero, new Vector2(24f, 14f), new Color(0.03f, 0.03f, 0.05f, 1f), 10);
fog.GetComponent<SpriteRenderer>().maskInteraction = SpriteMaskInteraction.VisibleOutsideMask;

// ---------- vision windows ----------
GameObject MakeWindow(string name, Transform owner, Vector2 offset, Vector2 size)
{
    var go = new GameObject(name);
    go.transform.SetParent(visionRoot, false);
    go.transform.localScale = new Vector3(size.x, size.y, 1f);

    var mask = go.AddComponent<SpriteMask>();
    mask.sprite = sprite;
    mask.isCustomRangeActive = true;
    mask.frontSortingLayerID = SortingLayer.NameToID("Default");
    mask.backSortingLayerID = SortingLayer.NameToID("Default");
    mask.frontSortingOrder = 100;
    mask.backSortingOrder = 0;

    var window = go.AddComponent<VisionWindow>();
    window.Configure(owner, offset);
    return go;
}

var leftWindow = MakeWindow("Window_OfLeftChar", leftChar.transform, new Vector2(8f, 0f), new Vector2(4f, 3f));
var rightWindow = MakeWindow("Window_OfRightChar", rightChar.transform, new Vector2(-8f, 0f), new Vector2(4f, 3f));

// ---------- managers ----------
var managers = new GameObject("Managers");
managers.transform.SetParent(root.transform, false);
var router = managers.AddComponent<InputRouter>();
var winChecker = managers.AddComponent<WinChecker>();
winChecker.Configure(leftPortal, rightPortal);

EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
bool saved = EditorSceneManager.SaveScene(SceneManager.GetActiveScene());

var sb = new StringBuilder();
sb.AppendLine($"saved={saved} scene={SceneManager.GetActiveScene().path}");
sb.AppendLine($"camera ortho={cam.orthographic} size={cam.orthographicSize} pos={cam.transform.position}");
sb.AppendLine($"leftWindow pos={leftWindow.transform.position} scale={leftWindow.transform.localScale}");
sb.AppendLine($"rightWindow pos={rightWindow.transform.position} scale={rightWindow.transform.localScale}");
sb.AppendLine($"leftChar pos={leftChar.transform.position}  rightChar pos={rightChar.transform.position}");
return sb.ToString();

using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

Color Sample(Texture2D t, Camera c, Vector2 world)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(world.x, world.y, 0f));
    int px = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int py = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(px, py);
}

string Tag(Color c) => $"({c.r:0.00},{c.g:0.00},{c.b:0.00})";

IEnumerator Run()
{
    var sb = new StringBuilder();
    var cam = Camera.main;
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();
    var leftRb = left.GetComponent<Rigidbody2D>();
    var rightRb = right.GetComponent<Rigidbody2D>();
    var leftWin = GameObject.Find("Window_OfLeftChar").GetComponent<VisionWindow>();
    var rightWin = GameObject.Find("Window_OfRightChar").GetComponent<VisionWindow>();
    var router = UnityEngine.Object.FindObjectOfType<InputRouter>();
    var win = UnityEngine.Object.FindObjectOfType<WinChecker>();

    sb.AppendLine($"refs: cam={cam != null} left={left != null} right={right != null} router={router != null} win={win != null}");

    // --- 1. settle ---
    for (int i = 0; i < 90; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[settle] left={left.transform.position} grounded={left.Grounded}");
    sb.AppendLine($"[settle] right={right.transform.position} grounded={right.Grounded}");

    // --- 2. offscreen render + pixel sampling (mask verification) ---
    const int W = 384, H = 216;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();

    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();

    Color throughLeftWindow = Sample(tex, cam, new Vector2(1.5f, -3.4f));   // 左角色视窗内、落在右侧平台上
    Color throughRightWindow = Sample(tex, cam, new Vector2(-1.5f, -3.4f)); // 右角色视窗内、落在左侧平台上
    Color outsideWindows = Sample(tex, cam, new Vector2(-6.0f, -3.4f));     // 视窗之外的地形
    Color characterPixel = Sample(tex, cam, new Vector2(left.transform.position.x, left.transform.position.y));
    Color emptySky = Sample(tex, cam, new Vector2(0f, 3.5f));

    RenderTexture.active = null;
    cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex);
    rt.Release();
    UnityEngine.Object.Destroy(rt);

    sb.AppendLine($"[mask] throughLeftWindow={Tag(throughLeftWindow)} (expect platform 0.42/0.45/0.52)");
    sb.AppendLine($"[mask] throughRightWindow={Tag(throughRightWindow)} (expect platform)");
    sb.AppendLine($"[mask] outsideWindows={Tag(outsideWindows)} (expect fog 0.03/0.03/0.05)");
    sb.AppendLine($"[mask] character={Tag(characterPixel)} (expect char 0.35/0.75/1.00)");
    sb.AppendLine($"[mask] emptySky={Tag(emptySky)} (expect fog)");

    // --- 3. window follows owner + offset ---
    leftRb.position = new Vector2(-5.0f, -2.4f);
    left.transform.position = new Vector3(-5.0f, -2.4f, 0f);
    for (int i = 0; i < 3; i++) yield return null;
    sb.AppendLine($"[follow] leftChar.x=-5.0 -> leftWindow.x={leftWin.transform.position.x:0.00} (expect 3.00)");

    // --- 4. fall respawn ---
    int before = left.RespawnCount;
    Vector2 safeBefore = left.SafePoint;
    leftRb.position = new Vector2(-6.5f, -10f);
    left.transform.position = new Vector3(-6.5f, -10f, 0f);
    for (int i = 0; i < 10; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[respawn] count {before}->{left.RespawnCount} pos={left.transform.position} safeBefore={safeBefore}");

    // --- 5. router modes ---
    router.SetMode(ControlMode.SinglePlayer);
    router.SetActiveSide(PlayerSide.Left);
    bool l1 = router.IsControlled(PlayerSide.Left), r1 = router.IsControlled(PlayerSide.Right);
    router.SetActiveSide(PlayerSide.Right);
    bool l2 = router.IsControlled(PlayerSide.Left), r2 = router.IsControlled(PlayerSide.Right);
    router.SetMode(ControlMode.TwoPlayer);
    bool l3 = router.IsControlled(PlayerSide.Left), r3 = router.IsControlled(PlayerSide.Right);
    sb.AppendLine($"[router] single/activeLeft => L={l1} R={r1} | single/activeRight => L={l2} R={r2} | twoPlayer => L={l3} R={r3}");
    router.SetMode(ControlMode.SinglePlayer);

    // --- 6. both portals -> win ---
    leftRb.position = new Vector2(-1f, -2.6f);
    rightRb.position = new Vector2(1f, -2.6f);
    for (int i = 0; i < 120; i++) yield return new WaitForFixedUpdate();
    var lp = GameObject.Find("Portal_Left").GetComponent<Portal>();
    var rp = GameObject.Find("Portal_Right").GetComponent<Portal>();
    sb.AppendLine($"[win] occupied L={lp.Occupied} R={rp.Occupied} held={win.HeldSeconds:0.00} completed={win.Completed}");

    return sb.ToString();
}

return Run();

