using ThreeCup.GrayBox;

Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/GrayBox/White4x4.png");
if (sprite == null) return "SPRITE_MISSING";

var sb = new StringBuilder();
Color ringColor = new Color(1f, 0.96f, 0.80f, 1f);

GameObject BuildHighlight(Transform player, string name)
{
    var existing = player.Find(name);
    if (existing != null) UnityEngine.Object.DestroyImmediate(existing.gameObject);

    var go = new GameObject(name);
    go.transform.SetParent(player, false);
    go.transform.localPosition = Vector3.zero;
    go.transform.localScale = Vector3.one * 1.4f;   // 父级 0.8 -> 世界 1.12，四周各露 0.16

    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = ringColor;
    sr.sortingOrder = 19;                            // 角色是 20，高亮在角色身后，只露出边框
    return go;
}

void Apply(string playerName, PlayerSide side)
{
    var player = GameObject.Find(playerName);
    var ring = BuildHighlight(player.transform, "Highlight");
    var visual = player.GetComponent<PlayerVisual>();
    visual.Configure(side, ring);
    sb.AppendLine($"{playerName}: ring world={Vector3.Scale(ring.transform.localScale, player.transform.localScale)} order={ring.GetComponent<SpriteRenderer>().sortingOrder} active={ring.activeSelf}");
}

Apply("Player_Left", PlayerSide.Left);
Apply("Player_Right", PlayerSide.Right);

EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
bool saved = EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
sb.AppendLine($"saved={saved}");
return sb.ToString();

using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

Color Sample(Texture2D t, Camera c, Vector2 world)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(world.x, world.y, 0f));
    int px = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int py = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(px, py);
}

string Tag(Color c) => $"({c.r:0.00},{c.g:0.00},{c.b:0.00})";

IEnumerator Run()
{
    var sb = new StringBuilder();
    var cam = Camera.main;
    var left = GameObject.Find("Player_Left");
    var right = GameObject.Find("Player_Right");
    var leftRing = left.transform.Find("Highlight").gameObject;
    var rightRing = right.transform.Find("Highlight").gameObject;
    var router = UnityEngine.Object.FindObjectOfType<InputRouter>();

    for (int i = 0; i < 60; i++) yield return new WaitForFixedUpdate();

    const int W = 384, H = 216;

    // ---------- pass 1: 默认主控 = Left ----------
    router.SetMode(ControlMode.SinglePlayer);
    router.SetActiveSide(PlayerSide.Left);
    yield return null;

    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();

    Vector2 lc = left.transform.position, rc = right.transform.position;
    sb.AppendLine($"[activeLeft] rings L={leftRing.activeSelf} R={rightRing.activeSelf}");
    sb.AppendLine($"  leftCharBody={Tag(Sample(tex, cam, lc))} expect 0.35/0.75/1.00");
    sb.AppendLine($"  leftRing     ={Tag(Sample(tex, cam, new Vector2(lc.x + 0.48f, lc.y)))} expect ring 1.00/0.96/0.80");
    sb.AppendLine($"  rightCharBody={Tag(Sample(tex, cam, rc))} expect 1.00/0.72/0.35 (not grey)");
    sb.AppendLine($"  rightRingGap ={Tag(Sample(tex, cam, new Vector2(rc.x + 0.48f, rc.y)))} expect fog 0.19/0.12/0.30");

    RenderTexture.active = null;

    // ---------- pass 2: 切到 Right ----------
    router.SetActiveSide(PlayerSide.Right);
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();

    sb.AppendLine($"[activeRight] rings L={leftRing.activeSelf} R={rightRing.activeSelf}");
    sb.AppendLine($"  leftCharBody ={Tag(Sample(tex, cam, lc))} expect 0.35/0.75/1.00 (not grey)");
    sb.AppendLine($"  leftRingGap  ={Tag(Sample(tex, cam, new Vector2(lc.x + 0.48f, lc.y)))} expect fog");
    sb.AppendLine($"  rightCharBody={Tag(Sample(tex, cam, rc))} expect 1.00/0.72/0.35");
    sb.AppendLine($"  rightRing    ={Tag(Sample(tex, cam, new Vector2(rc.x + 0.48f, rc.y)))} expect ring");

    RenderTexture.active = null;
    cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex);
    rt.Release();
    UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-Highlight]\n" + sb);
}

return Run();

