    {
        float dist = x - 3.5f;
        sb.AppendLine($"  x={x:0.0} d={dist:+0.0;-0.0} => {Tag(Sample(tex, cam, x, -2.0f))}");
    }

    sb.AppendLine("窗口上边缘 y=-0.9 处的纵向扫描 (x=1.5)：");
    foreach (float y in new[] { -1.1f, -0.9f, -0.8f, -0.7f, -0.5f, -0.3f })
    {
        float dist = y - (-0.9f);
        sb.AppendLine($"  y={y:0.0} d={dist:+0.0;-0.0} => {Tag(Sample(tex, cam, 1.5f, y))}");
    }

    sb.AppendLine($"参考: 背景 sky={Tag(cam.backgroundColor)}  遮盖 fog={Tag(GameObject.Find("Fog").GetComponent<SpriteRenderer>().color)}");

    RenderTexture.active = null;
    cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex);
    rt.Release();
    UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-Feather]\n" + sb);
}

