var sb = new StringBuilder();
Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/GrayBox/White4x4.png");
if (sprite == null) return "SPRITE_MISSING";

const float thickness = 0.8f;
Color platformColor = new Color(0.42f, 0.45f, 0.52f, 1f);

GameObject Quad(Transform parent, string name, Vector2 center, Vector2 size, Color color, int order)
{
    var go = new GameObject(name);
    go.transform.SetParent(parent, false);
    go.transform.position = new Vector3(center.x, center.y, 0f);
    go.transform.localScale = new Vector3(size.x, size.y, 1f);
    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = color;
    sr.sortingOrder = order;
    return go;
}

GameObject BuildLevel(string id,
    (string name, float minX, float maxX, float top)[] plats,
    Vector2 spawnL, Vector2 spawnR,
    Vector2 portalL, Vector2 portalR)
{
    var temp = new GameObject(id);

    var terrain = new GameObject("Terrain").transform;
    terrain.SetParent(temp.transform, false);

    foreach (var p in plats)
    {
        float w = p.maxX - p.minX;
        var go = Quad(terrain, p.name, new Vector2((p.minX + p.maxX) * 0.5f, p.top - thickness * 0.5f),
                      new Vector2(w, thickness), platformColor, 0);
        go.AddComponent<BoxCollider2D>().size = Vector2.one;
    }

    var portals = new GameObject("Portals").transform;
    portals.SetParent(temp.transform, false);

    void MakePortal(string pname, Vector2 center, PlayerSide side, Color color)
    {
        var go = Quad(portals, pname, center, new Vector2(1.0f, 1.8f), color, 5);
        var col = go.AddComponent<BoxCollider2D>();
        col.isTrigger = true;
        col.size = Vector2.one;
        go.AddComponent<Portal>().Configure(side);
    }

    MakePortal("Portal_Left", portalL, PlayerSide.Left, new Color(0.25f, 0.85f, 0.55f, 1f));
    MakePortal("Portal_Right", portalR, PlayerSide.Right, new Color(0.85f, 0.55f, 0.25f, 1f));

    void MakeSpawn(string sname, Vector2 pos)
    {
        var go = new GameObject(sname);
        go.transform.SetParent(temp.transform, false);
        go.transform.position = new Vector3(pos.x, pos.y, 0f);
    }

    MakeSpawn("Spawn_Left", spawnL);
    MakeSpawn("Spawn_Right", spawnR);

    return temp;
}

string SaveLevel(string id, string displayName, GameObject temp, List<LevelConfig> configs)
