using UnityEngine;
using ThreeCup.GrayBox;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();

    for (int i = 0; i < 60; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[start] level={session.Current.LevelId} index={session.CurrentIndex}");

    for (int round = 0; round < 3; round++)
    {
        string before = session.Current.LevelId;

        // 站姿检查：两个角色应该都落在地面上
        sb.AppendLine($"[{before}] grounded L={left.Grounded} R={right.Grounded} posL={left.transform.position} posR={right.transform.position}");

        var lp = GameObject.Find("Portal_Left");
        var rp = GameObject.Find("Portal_Right");
        if (lp == null || rp == null) { sb.AppendLine($"[{before}] PORTAL_MISSING"); break; }

        sb.AppendLine($"[{before}] portalPos L={lp.transform.position} R={rp.transform.position}");

        left.GetComponent<Rigidbody2D>().position = lp.transform.position;
        right.GetComponent<Rigidbody2D>().position = rp.transform.position;

        float t0 = Time.time;
        while (Time.time - t0 < 3.0f) yield return null;

        sb.AppendLine($"[{before}] -> after win: level={session.Current.LevelId} index={session.CurrentIndex}");

        for (int i = 0; i < 60; i++) yield return new WaitForFixedUpdate();
    }

    sb.AppendLine($"[final] level={session.Current.LevelId} grounded L={left.Grounded} R={right.Grounded}");

    Debug.Log("[GrayBox-Advance]\n" + sb);
}

return Run();

