Color Sample(Texture2D t, Camera c, float x, float y)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(x, y, 0f));
    int px = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int py = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(px, py);
}

