using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 通关条件：两名角色同时待在自己的终点里。
    /// </summary>
    public sealed class WinChecker : MonoBehaviour
    {
        [SerializeField] LevelGoal leftGoal;
        [SerializeField] LevelGoal rightGoal;
        [SerializeField] float requiredSeconds = 0.5f;

        public event System.Action Won;

        public bool Completed { get; private set; }
        public float HeldSeconds => heldSeconds;

        float heldSeconds;

        public void Configure(LevelGoal left, LevelGoal right)
        {
            leftGoal = left;
            rightGoal = right;
        }

        public void ResetState()
        {
            heldSeconds = 0f;
            Completed = false;
        }

        void Update()
        {
            if (Completed) return;

            bool bothInside = leftGoal != null && rightGoal != null &&
                              leftGoal.Occupied && rightGoal.Occupied;

            heldSeconds = bothInside ? heldSeconds + Time.deltaTime : 0f;
            if (heldSeconds < requiredSeconds) return;

            Completed = true;
            Debug.Log("[GrayBox] 通关：两名角色同时站在各自的终点内");
            Won?.Invoke();
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    [RequireComponent(typeof(Rigidbody2D))]
    public sealed class PlayerMotor2D : MonoBehaviour
    {
        [Header("Identity")]
        [SerializeField] PlayerSide side = PlayerSide.Left;

        [Header("Movement")]
        [SerializeField] float moveSpeed = 5.5f;
        [SerializeField] float jumpVelocity = 10.5f;

        [Header("Death")]
        [SerializeField] float fallRespawnY = -6f;

        /// <summary>机关持续判定时防止一帧扣掉多条命。</summary>
        [SerializeField] float invulnerabilitySeconds = 0.5f;

        [Header("Ground Check")]
        [SerializeField] LayerMask groundMask = ~0;
        [SerializeField] float groundRayLength = 0.1f;

        /// <summary>掉坑和机关致死共用这一条路径。</summary>
        public event System.Action<PlayerSide, DeathCause> Died;

        public PlayerSide Side => side;
        public bool Grounded { get; private set; }
        public bool Frozen { get; private set; }
        public bool IsInvulnerable => Time.time < invulnerableUntil;
        public int DeathCount { get; private set; }
        public Vector2 SafePoint => safePoint;

        Rigidbody2D body;
        Collider2D bodyCollider;
        InputRouter router;
        Vector2 safePoint;
        float horizontalInput;
        bool jumpRequested;
        bool frozen;
        float invulnerableUntil;

        public void Configure(PlayerSide newSide) => side = newSide;

        public void ResetSafePoint(Vector2 position) => safePoint = position;

        /// <summary>Freezes the character in place, used when the level is failed.</summary>
        public void SetFrozen(bool value)
        {
            frozen = value;
            Frozen = value;

            if (body == null) body = GetComponent<Rigidbody2D>();
            if (body == null) return;

            body.velocity = Vector2.zero;
            body.simulated = !value;
        }

        /// <summary>唯一的死亡入口。掉坑、尖刺、激光都走这里。</summary>
        public void Kill(DeathCause cause)
        {
            if (frozen) return;
            if (IsInvulnerable) return;

            invulnerableUntil = Time.time + invulnerabilitySeconds;

            body.velocity = Vector2.zero;
            body.position = safePoint;
            transform.position = safePoint;
            DeathCount++;

            Died?.Invoke(side, cause);
        }

        void Awake()
        {
            body = GetComponent<Rigidbody2D>();
            bodyCollider = GetComponent<Collider2D>();
            safePoint = body.position;
        }

        void Start()
        {
            router = FindObjectOfType<InputRouter>();
            if (router != null) router.Register(this);
        }

        void OnDestroy()
        {
            if (router != null) router.Unregister(this);
        }

        void Update()
        {
            if (frozen)
            {
                horizontalInput = 0f;
                jumpRequested = false;
                return;
            }

            if (router == null) router = FindObjectOfType<InputRouter>();
            if (router == null)
            {
                horizontalInput = 0f;
                jumpRequested = false;
                return;
            }

            horizontalInput = router.GetHorizontal(side);
            if (router.GetJumpDown(side)) jumpRequested = true;
        }

        void FixedUpdate()
        {
            if (frozen) return;

            Grounded = CheckGrounded();

            Vector2 velocity = body.velocity;
            velocity.x = horizontalInput * moveSpeed;
            if (jumpRequested && Grounded) velocity.y = jumpVelocity;
            jumpRequested = false;
            body.velocity = velocity;

            // The last spot we stood still on is the safest place to come back to.
            if (Grounded && Mathf.Abs(velocity.y) < 0.6f) safePoint = body.position;

            if (body.position.y < fallRespawnY) Kill(DeathCause.Fall);
        }

        /// <summary>Ray starts just below the collider so it cannot hit ourselves.</summary>
        bool CheckGrounded()
        {
            Bounds bounds = bodyCollider.bounds;
            float originY = bounds.min.y - 0.02f;
            float inset = 0.05f;

            if (Physics2D.Raycast(new Vector2(bounds.center.x, originY), Vector2.down, groundRayLength, groundMask)) return true;
            if (Physics2D.Raycast(new Vector2(bounds.min.x + inset, originY), Vector2.down, groundRayLength, groundMask)) return true;
            if (Physics2D.Raycast(new Vector2(bounds.max.x - inset, originY), Vector2.down, groundRayLength, groundMask)) return true;
            return false;
        }
    }
}

using System.Collections;
using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// Instantiates one level prefab, drops the two characters on its spawn markers,
    /// rewires the win condition, counts deaths and moves on when the level is cleared.
    /// Levels never reference each other; only the catalog knows the order.
    /// </summary>
    public sealed class LevelSession : MonoBehaviour
    {
        [Header("Scene references")]
        [SerializeField] LevelCatalog catalog;
        [SerializeField] PlayerMotor2D leftPlayer;
        [SerializeField] PlayerMotor2D rightPlayer;
        [SerializeField] WinChecker winChecker;
        [SerializeField] Transform levelRoot;
        [SerializeField] VisionWindow leftWindow;
        [SerializeField] VisionWindow rightWindow;

        [Header("Rules")]
        [SerializeField] int livesPerLevel = 3;
        [SerializeField] float advanceDelay = 1.2f;

        [Header("Prototype")]
        [SerializeField] bool enableHotkeys = true;
        [SerializeField] int startIndex;

        public event System.Action FailedEvent;
        public event System.Action<int> LivesChanged;

        GameObject instance;
        LevelConfig current;
        int currentIndex = -1;
        int deaths;
        Coroutine advance;

        public LevelConfig Current => current;
        public GameObject Instance => instance;
        public int CurrentIndex => currentIndex;
        public bool Failed { get; private set; }
        public int LivesPerLevel => livesPerLevel;
        public int LivesRemaining => Mathf.Max(0, livesPerLevel - deaths);

        void Start()
        {
            if (winChecker != null) winChecker.Won += HandleWon;
            if (leftPlayer != null) leftPlayer.Died += HandleDeath;
            if (rightPlayer != null) rightPlayer.Died += HandleDeath;

            if (catalog != null && catalog.Count > 0) LoadIndex(startIndex);
        }

        void OnDestroy()
        {
            if (winChecker != null) winChecker.Won -= HandleWon;
            if (leftPlayer != null) leftPlayer.Died -= HandleDeath;
            if (rightPlayer != null) rightPlayer.Died -= HandleDeath;
        }

        void Update()
        {
            if (!enableHotkeys || catalog == null) return;

            for (int i = 0; i < 9 && i < catalog.Count; i++)
            {
                if (Input.GetKeyDown((KeyCode)((int)KeyCode.Alpha1 + i)))
                {
                    LoadIndex(i);
                    return;
                }
            }

            if (Input.GetKeyDown(KeyCode.R)) RetryLevel();
        }

        public void RetryLevel() => LoadIndex(currentIndex);

        public void Load(LevelConfig config) => LoadInternal(config, IndexOf(config));

        public void LoadIndex(int index)
        {
            if (catalog == null) return;

            LoadInternal(catalog.Get(index), index);
        }

        void LoadInternal(LevelConfig config, int index)
        {
            if (config == null || config.LevelPrefab == null) return;

            if (advance != null)
            {
                StopCoroutine(advance);
                advance = null;
            }

            Unload();

            instance = Instantiate(config.LevelPrefab, levelRoot != null ? levelRoot : null);
            instance.name = config.LevelId;
            current = config;
            currentIndex = index;

            deaths = 0;
            Failed = false;
            SetPlayersFrozen(false);

            PlacePlayer(leftPlayer, "Spawn_Left");
            PlacePlayer(rightPlayer, "Spawn_Right");
            ApplyWindows(config);
            WireGoals();

            LivesChanged?.Invoke(LivesRemaining);
        }

        public void Unload()
        {
            if (instance != null) Destroy(instance);
            instance = null;
        }

        void ApplyWindows(LevelConfig config)
        {
            if (leftWindow != null && leftPlayer != null)
            {
                leftWindow.SetSize(config.WindowSize);
                leftWindow.Configure(leftPlayer.transform, config.LeftWindowOffset);
            }

            if (rightWindow != null && rightPlayer != null)
            {
                rightWindow.SetSize(config.WindowSize);
                rightWindow.Configure(rightPlayer.transform, config.RightWindowOffset);
            }
        }

        void PlacePlayer(PlayerMotor2D player, string markerName)
        {
            if (player == null || instance == null) return;

            var marker = FindDeep(instance.transform, markerName);
            if (marker == null)
            {
                Debug.LogWarning($"[GrayBox] 关卡 {instance.name} 缺少出生点标记 {markerName}");
                return;
            }

            Vector2 target = marker.position;
            var body = player.GetComponent<Rigidbody2D>();
            if (body != null)
            {
                body.velocity = Vector2.zero;
                body.position = target;
            }

            player.transform.position = target;
            player.ResetSafePoint(target);
        }

        void WireGoals()
        {
            if (winChecker == null || instance == null) return;

            var left = FindDeep(instance.transform, "Goal_Left");
            var right = FindDeep(instance.transform, "Goal_Right");

            winChecker.Configure(
                left != null ? left.GetComponent<LevelGoal>() : null,
                right != null ? right.GetComponent<LevelGoal>() : null);
            winChecker.ResetState();
        }

        void HandleDeath(PlayerSide side, DeathCause cause)
        {
            if (Failed) return;

            deaths++;
            Debug.Log($"[GrayBox] {side} 死亡（{cause}）{deaths}/{livesPerLevel}，剩余 {LivesRemaining}");
            LivesChanged?.Invoke(LivesRemaining);

            if (deaths >= livesPerLevel) FailLevel();
        }

        void FailLevel()
        {
            Failed = true;
            SetPlayersFrozen(true);

            // 失败窗口以后接 FailedEvent
            Debug.Log("[GrayBox] 关卡失败：生命耗尽");
            FailedEvent?.Invoke();
        }

        void SetPlayersFrozen(bool value)
        {
            if (leftPlayer != null) leftPlayer.SetFrozen(value);
            if (rightPlayer != null) rightPlayer.SetFrozen(value);
        }

        void HandleWon()
        {
            if (advance != null) return;

            advance = StartCoroutine(AdvanceAfterDelay());
        }

        IEnumerator AdvanceAfterDelay()
        {
            yield return new WaitForSeconds(advanceDelay);
            advance = null;

            int next = currentIndex + 1;
            if (catalog != null && next < catalog.Count)
            {
                LoadIndex(next);
                yield break;
            }

            // 最后一关：以后把胜利窗口挂在这里
            Debug.Log("[GrayBox] 已是最后一关");
        }

        int IndexOf(LevelConfig config)
        {
            if (catalog == null || config == null) return -1;

            for (int i = 0; i < catalog.Count; i++)
                if (catalog.Get(i) == config) return i;

            return -1;
        }

        static Transform FindDeep(Transform root, string name)
        {
            foreach (var t in root.GetComponentsInChildren<Transform>(true))
                if (t.name == name) return t;

            return null;
        }
    }
}

using System.Collections.Generic;
using System.Text;
