using System.Text;
using UnityEditor;
using UnityEngine;
using ThreeCup.GrayBox;

var sb = new StringBuilder();

Transform FindDeep(Transform root, string name)
{
    foreach (var t in root.GetComponentsInChildren<Transform>(true))
        if (t.name == name) return t;
    return null;
}

foreach (var path in new[] { "Assets/Prefabs/GrayBox/Level_L001.prefab", "Assets/Prefabs/GrayBox/L002.prefab", "Assets/Prefabs/GrayBox/L003.prefab" })
{
    var root = PrefabUtility.LoadPrefabContents(path);
    if (root == null) { sb.AppendLine($"{path} LOAD_FAIL"); continue; }

    int renamed = 0;
    var map = new (string from, string to)[]
    {
        ("Portal_Left", "Goal_Left"),
        ("Portal_Right", "Goal_Right"),
        ("Portals", "Goals"),
    };

    foreach (var (from, to) in map)
    {
        var t = FindDeep(root.transform, from);
        if (t != null) { t.name = to; renamed++; }
    }

    // 让排序号统一从 GrayBoxSorting 取
    foreach (var sr in root.GetComponentsInChildren<SpriteRenderer>(true))
    {
        if (sr.gameObject.name.StartsWith("Goal_")) sr.sortingOrder = GrayBoxSorting.Mechanism;
        else if (sr.gameObject.name.StartsWith("Plat_")) sr.sortingOrder = GrayBoxSorting.Terrain;
    }

    PrefabUtility.SaveAsPrefabAsset(root, path);
    PrefabUtility.UnloadPrefabContents(root);

    var check = AssetDatabase.LoadAssetAtPath<GameObject>(path);
    int missing = 0;
    foreach (var c in check.GetComponentsInChildren<Component>(true))
        if (c == null) missing++;

    string names = "";
    var goals = check.transform.Find("Goals");
    if (goals != null) foreach (Transform c in goals) names += c.name + " ";

    sb.AppendLine($"{path}: renamed={renamed} missingScripts={missing} goals=[{names.Trim()}]");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return sb.ToString();

using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();
    var win = UnityEngine.Object.FindObjectOfType<WinChecker>();

    for (int i = 0; i < 60; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[init] level={session.Current.LevelId} lives={session.LivesRemaining} failed={session.Failed}");

    // ---- 死亡路径统一：直接调用 Kill(Hazard) ----
    left.Kill(DeathCause.Hazard);
    sb.AppendLine($"[kill1] lives={session.LivesRemaining} invuln={left.IsInvulnerable}");

    left.Kill(DeathCause.Hazard);
    sb.AppendLine($"[kill2 immediate] lives={session.LivesRemaining}  (应仍为 2，被无敌帧吸收)");

    float until = Time.time + 0.7f;
    while (Time.time < until) yield return null;

    left.Kill(DeathCause.Hazard);
    sb.AppendLine($"[kill3] lives={session.LivesRemaining} failed={session.Failed}");

    until = Time.time + 0.7f;
    while (Time.time < until) yield return null;

    left.Kill(DeathCause.Hazard);
    sb.AppendLine($"[kill4] lives={session.LivesRemaining} failed={session.Failed} frozen={left.Frozen}");

    // ---- 重试 ----
    session.RetryLevel();
    yield return null;
    for (int i = 0; i < 40; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[retry] lives={session.LivesRemaining} failed={session.Failed} frozen={left.Frozen} pos={left.transform.position}");

    // ---- 改名后通关仍然成立 ----
    var gl = GameObject.Find("Goal_Left");
    var gr = GameObject.Find("Goal_Right");
    sb.AppendLine($"[goals] left={(gl != null)} right={(gr != null)} component={(gl != null ? gl.GetComponent<LevelGoal>() != null : false)}");

    left.GetComponent<Rigidbody2D>().position = gl.transform.position;
    right.GetComponent<Rigidbody2D>().position = gr.transform.position;

    float t0 = Time.time;
    while (Time.time - t0 < 2.5f && !win.Completed) yield return null;
    sb.AppendLine($"[win] completed={win.Completed} level={session.Current.LevelId}");

    Debug.Log("[GrayBox-Stage0]\n" + sb);
}

return Run();

