using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using ThreeCup.GrayBox;
using ThreeCup.EditorTools;

var sb = new StringBuilder();

// 场景里不应再残留旧 Portal 类型
int legacy = 0;
foreach (var root in SceneManager.GetActiveScene().GetRootGameObjects())
    foreach (var c in root.GetComponentsInChildren<Component>(true))
        if (c == null) legacy++;

sb.AppendLine($"scene missingScripts={legacy}");

bool saved = EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
sb.AppendLine($"saved={saved}");

sb.AppendLine("scripts tree:");
void Dump(string folder, int depth)
{
    foreach (var sub in AssetDatabase.GetSubFolders(folder))
    {
        sb.AppendLine(new string(' ', depth * 2) + "- " + System.IO.Path.GetFileName(sub) + "/");
        Dump(sub, depth + 1);
    }
    foreach (var guid in AssetDatabase.FindAssets("t:Script", new[] { folder }))
    {
        var p = AssetDatabase.GUIDToAssetPath(guid);
        if (System.IO.Path.GetDirectoryName(p).Replace('\\', '/') != folder) continue;
        sb.AppendLine(new string(' ', depth * 2) + "  " + System.IO.Path.GetFileName(p));
    }
}
Dump("Assets/Scripts", 0);

LevelTools.ValidateLevels();
return sb.ToString();

