using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

Color Sample(Texture2D t, Camera c, float x, float y)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(x, y, 0f));
    int px = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int py = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(px, py);
}

string Tag(Color c) => $"({c.r:0.00},{c.g:0.00},{c.b:0.00})";

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var leftRb = left.GetComponent<Rigidbody2D>();

    session.LoadIndex(3);
    yield return null;
    for (int i = 0; i < 60; i++) yield return new WaitForFixedUpdate();

    var hazards = session.Instance.GetComponentsInChildren<Hazard>(true);
    sb.AppendLine($"[load] level={session.Current.LevelId} lives={session.LivesRemaining} hazards={hazards.Length}");

    var laser = GameObject.Find("Laser_Left").GetComponent<TimedToggler>();
    var pulse = GameObject.Find("Laser_Left").transform.Find("Pulse").gameObject;
    sb.AppendLine($"[laser] toggler found={laser != null} pulse={pulse != null}");

    var states = new StringBuilder();
    float t0 = Time.time;
    while (Time.time - t0 < 3.2f)
    {
        states.Append(laser.IsOn ? "1" : "0");
        yield return new WaitForSeconds(0.25f);
    }
    sb.AppendLine($"[laser] IsOn 采样(每0.25s): {states}");
    sb.AppendLine($"[laser] pulse.activeSelf={pulse.activeSelf} hazardEnabled={(pulse.GetComponent<Hazard>() != null ? pulse.GetComponent<Hazard>().enabled : false)}");

    // ---- 机关在遮罩下不可见 ----
    var cam = Camera.main;
    const int W = 384, H = 216;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0); tex.Apply();

    Color spikePixel = Sample(tex, cam, -6.3f, -2.8f);
    sb.AppendLine($"[fog] 尖刺位置(-6.3,-2.8) -> {Tag(spikePixel)}  遮盖色={Tag(GameObject.Find("Fog").GetComponent<SpriteRenderer>().color)} (应等于遮盖色)");

    RenderTexture.active = null; cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);

    // ---- 触碰致死 ----
    leftRb.position = new Vector2(-6.3f, -2.6f);
    for (int i = 0; i < 12; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[spike] lives={session.LivesRemaining} deaths={left.DeathCount} pos={left.transform.position}");

    Debug.Log("[GrayBox-Hazard]\n" + sb);
}

return Run();

