        if (col == null)
        {
            report.AppendLine($"  {label} 机关 {hazard.name} 上没有碰撞体");
            problems++;
            continue;
        }

        if (!col.isTrigger)
        {
            report.AppendLine($"  {label} 机关 {hazard.name} 的碰撞体不是 Trigger，会挡住角色");
            problems++;
        }

        foreach (var spawn in spawns)
        {
            if (!col.bounds.Contains(spawn.position)) continue;

            report.AppendLine($"  {label} 出生点 {spawn.name} 落在机关 {hazard.name} 里");
            problems++;
        }
    }

    return problems;
}

