static bool TryGetWorldBounds(Collider2D col, out Bounds bounds)
{
    var t = col.transform;
    var scale = t.lossyScale;
    if (col is BoxCollider2D box)
    {
        Vector3 size = new Vector3(box.size.x * Mathf.Abs(scale.x), box.size.y * Mathf.Abs(scale.y), 1f);
        Vector3 center = t.position + new Vector3(box.offset.x * scale.x, box.offset.y * scale.y, 0f);
        bounds = new Bounds(center, size);
        return true;
