var sb = new StringBuilder();
Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/GrayBox/White4x4.png");
const string path = "Assets/Prefabs/GrayBox/L004.prefab";

var root = PrefabUtility.LoadPrefabContents(path);
if (root == null) return "PREFAB_LOAD_FAIL";

var old = root.transform.Find("Checkpoints");
if (old != null) UnityEngine.Object.DestroyImmediate(old.gameObject);

var container = new GameObject("Checkpoints").transform;
container.SetParent(root.transform, false);

void MakeCheckpoint(string name, float x, PlayerSide side, int order)
{
    var go = new GameObject(name);
    go.transform.SetParent(container, false);
    go.transform.localPosition = new Vector3(x, -2.6f, 0f);
    go.transform.localScale = new Vector3(0.6f, 1.6f, 1f);

    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = new Color(0.30f, 0.90f, 0.90f, 0.85f);
    sr.sortingOrder = GrayBoxSorting.Hint;

    var col = go.AddComponent<BoxCollider2D>();
    col.isTrigger = true;
    col.size = Vector2.one;

    go.AddComponent<Checkpoint>().Configure(side, order);
}

MakeCheckpoint("Checkpoint_Left_1", -4.1f, PlayerSide.Left, 1);
MakeCheckpoint("Checkpoint_Right_1", 4.1f, PlayerSide.Right, 1);

PrefabUtility.SaveAsPrefabAsset(root, path);
PrefabUtility.UnloadPrefabContents(root);

var check = AssetDatabase.LoadAssetAtPath<GameObject>(path);
foreach (var cp in check.GetComponentsInChildren<Checkpoint>(true))
{
    var col = cp.GetComponent<BoxCollider2D>();
    var s = cp.transform.lossyScale;
    sb.AppendLine($"{cp.name}: side={cp.Side} order={cp.Order} pos={cp.transform.position} size=({col.size.x * s.x:0.00},{col.size.y * s.y:0.00}) order(sorting)={cp.GetComponent<SpriteRenderer>().sortingOrder}");
}

AssetDatabase.SaveAssets();
return sb.ToString();

