    sb.AppendLine($"[die] lives={session.LivesRemaining} deaths={left.DeathCount} pos={left.transform.position} (应为存档点 -4.10)");

    // 4) 重开关卡应清空存档进度
    session.RetryLevel();
    yield return null;
    for (int i = 0; i < 40; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[retry] respawnPoint={left.RespawnPoint} pos={left.transform.position} (应回到出生点)");

