using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();

    session.LoadIndex(3);
    yield return null;
    for (int i = 0; i < 100; i++) yield return new WaitForFixedUpdate();

    sb.AppendLine($"[load] level={session.Current.LevelId} lives={session.LivesRemaining} failed={session.Failed}");
    sb.AppendLine($"[spawn] left={left.transform.position} right={right.transform.position}");

    // 走到存档点
    left.GetComponent<Rigidbody2D>().position = new Vector2(-3.9f, -2.6f);
    right.GetComponent<Rigidbody2D>().position = new Vector2(3.9f, -2.6f);
    for (int i = 0; i < 12; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[checkpoint] L={left.RespawnPoint} R={right.RespawnPoint}");

    // 踩尖刺 -> 回存档点
    left.GetComponent<Rigidbody2D>().position = new Vector2(-5.0f, -2.6f);
    for (int i = 0; i < 15; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[spike] lives={session.LivesRemaining} pos={left.transform.position}");

    // 激光周期
    var laser = GameObject.Find("Laser_Left").GetComponent<TimedToggler>();
    var states = new StringBuilder();
    float t0 = Time.time;
    while (Time.time - t0 < 3.1f) { states.Append(laser.IsOn ? "1" : "0"); yield return new WaitForSeconds(0.25f); }
    sb.AppendLine($"[laser] {states}");

    // 两人同时到终点
    var gl = GameObject.Find("Goal_Left");
    var gr = GameObject.Find("Goal_Right");
    left.GetComponent<Rigidbody2D>().position = gl.transform.position;
    right.GetComponent<Rigidbody2D>().position = gr.transform.position;
    var win = UnityEngine.Object.FindObjectOfType<WinChecker>();
    t0 = Time.time;
    while (Time.time - t0 < 2.5f && !win.Completed) yield return null;
    sb.AppendLine($"[win] completed={win.Completed}");

    Debug.Log("[GrayBox-L004Rework]\n" + sb);
}

return Run();

using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

Color Sample(Texture2D t, Camera c, float x, float y)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(x, y, 0f));
    int px = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int py = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(px, py);
}

string Tag(Color c) => $"({c.r:0.00},{c.g:0.00},{c.b:0.00})";

IEnumerator Run()
{
    var sb = new StringBuilder();
    var cam = Camera.main;
    for (int i = 0; i < 60; i++) yield return new WaitForFixedUpdate();

    const int W = 384, H = 216;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0); tex.Apply();

    var fog = GameObject.Find("Fog").GetComponent<SpriteRenderer>().color;
    sb.AppendLine($"存档点(-3.9,-2.6) = {Tag(Sample(tex, cam, -3.9f, -2.6f))}  (应偏青色，常亮可见)");
    sb.AppendLine($"尖刺  (-5.0,-2.8) = {Tag(Sample(tex, cam, -5.0f, -2.8f))}  (应等于遮盖色)");
    sb.AppendLine($"激光  (-1.7,-1.5) = {Tag(Sample(tex, cam, -1.7f, -1.5f))}");
    sb.AppendLine($"遮盖色            = {Tag(fog)}");

    RenderTexture.active = null; cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-L004Visual]\n" + sb);
}

return Run();

