using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using ThreeCup.GrayBox;

var sb = new StringBuilder();
var managers = GameObject.Find("Managers");

if (managers.GetComponent<DeathPopup>() == null) managers.AddComponent<DeathPopup>();

var session = managers.GetComponent<LevelSession>();
var so = new SerializedObject(session);
var popup = so.FindProperty("deathPopupSeconds");
if (popup.floatValue <= 0f) { popup.floatValue = 2f; so.ApplyModifiedPropertiesWithoutUndo(); }

sb.AppendLine($"deathPopupSeconds={popup.floatValue}");
sb.AppendLine($"managers: {string.Join(", ", System.Array.ConvertAll(managers.GetComponents<Component>(), c => c.GetType().Name))}");

EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
bool saved = EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
sb.AppendLine($"saved={saved}");
return sb.ToString();

using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();

    session.LoadIndex(3);
    yield return null;
    for (int i = 0; i < 90; i++) yield return new WaitForFixedUpdate();
    sb.AppendLine($"[load] level={session.Current.LevelId} lives={session.LivesRemaining}");

    // ---- 第一次死亡 ----
    left.Kill(DeathCause.Hazard);
    yield return null;
    sb.AppendLine($"[death1] popup={session.DeathPopupVisible} side={session.DeathPopupSide} lives={session.LivesRemaining}");
    sb.AppendLine($"[death1] frozen L={left.Frozen} R={right.Frozen} simulated L={left.GetComponent<Rigidbody2D>().simulated} R={right.GetComponent<Rigidbody2D>().simulated}");

    float t0 = Time.time;
    yield return new WaitForSeconds(1.0f);
    sb.AppendLine($"[death1 +1.0s] popup={session.DeathPopupVisible} frozenL={left.Frozen}  (应仍在弹窗、仍锁)");

    yield return new WaitForSeconds(1.4f);
    sb.AppendLine($"[death1 +2.4s] popup={session.DeathPopupVisible} frozenL={left.Frozen}  (应已恢复)");

    // ---- 第二次死亡（右侧）----
    right.Kill(DeathCause.Fall);
    yield return null;
    sb.AppendLine($"[death2] popup={session.DeathPopupVisible} side={session.DeathPopupSide} lives={session.LivesRemaining}");
    yield return new WaitForSeconds(2.3f);
    sb.AppendLine($"[death2 +2.3s] popup={session.DeathPopupVisible} frozenR={right.Frozen}");

    // ---- 第三次死亡 -> 判负，弹窗结束后保持冻结 ----
    left.Kill(DeathCause.Hazard);
    yield return null;
    sb.AppendLine($"[death3] popup={session.DeathPopupVisible} lives={session.LivesRemaining}");
    yield return new WaitForSeconds(2.4f);
    sb.AppendLine($"[death3 +2.4s] popup={session.DeathPopupVisible} failed={session.Failed} frozenL={left.Frozen} frozenR={right.Frozen}");

    Debug.Log("[GrayBox-DeathPopup]\n" + sb);
}

return Run();

