namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 可被开关驱动的对象。放在 Mechanism 下，Switch 通过组件引用找到它。
    /// </summary>
    public interface ISwitchTarget
    {
        void SetActive(bool active);
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 可开关的方块：关掉时碰撞体失效、视觉隐藏，打开时恢复。
    /// 初始状态由 startActive 决定，Switch 只负责在切换时通知它。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class ToggleBlock : MonoBehaviour, ISwitchTarget
    {
        [SerializeField] bool startActive = true;
        [SerializeField] bool visibleWhenInactive;
        [SerializeField] Color activeColor = new Color(0.48f, 0.72f, 0.42f, 1f);
        [SerializeField] Color inactiveColor = new Color(0.48f, 0.72f, 0.42f, 0.18f);

        SpriteRenderer sprite;
        Collider2D body;

        public bool Active { get; private set; }

        void Awake()
        {
            sprite = GetComponent<SpriteRenderer>();
            body = GetComponent<Collider2D>();
            Apply(startActive);
        }

        public void SetActive(bool active) => Apply(active);

        void Apply(bool active)
        {
            Active = active;

            if (body != null) body.enabled = active;

            if (sprite == null) return;

            sprite.enabled = active || visibleWhenInactive;
            sprite.color = active ? activeColor : inactiveColor;
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 踩上去（或碰到）就驱动一组 ISwitchTarget 的开关。
    /// 目标可以放在另一半屏，这就是「跨屏开关」——踩下后对面那侧长出路来。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class Switch : MonoBehaviour
    {
        [Tooltip("挂任意实现了 ISwitchTarget 的组件，可以跨屏引用")]
        [SerializeField] MonoBehaviour[] targets;

        [Tooltip("按下后保持，不再响应离开")]
        [SerializeField] bool oneShot = true;

        [Tooltip("可反复触发时，离开是否复原")]
        [SerializeField] bool revertOnExit;

        [SerializeField] Color idleColor = new Color(0.75f, 0.62f, 0.30f, 1f);
        [SerializeField] Color pressedColor = new Color(0.35f, 0.90f, 0.60f, 1f);

        SpriteRenderer sprite;
        int occupants;
        bool pressed;

        public bool Pressed => pressed;

        void Awake() => sprite = GetComponent<SpriteRenderer>();

        void OnTriggerEnter2D(Collider2D other)
        {
            if (other.GetComponent<PlayerMotor2D>() == null) return;

            occupants++;
            SetPressed(true);
        }

        void OnTriggerExit2D(Collider2D other)
        {
            if (other.GetComponent<PlayerMotor2D>() == null) return;

            occupants = Mathf.Max(0, occupants - 1);
            if (oneShot || !revertOnExit || occupants > 0) return;

            SetPressed(false);
        }

        void SetPressed(bool value)
        {
            // 一次性开关按下后不再改变任何目标
            if (oneShot && pressed) return;
            if (pressed == value) return;

            pressed = value;

            if (sprite != null) sprite.color = pressed ? pressedColor : idleColor;

            if (targets == null) return;

            foreach (var target in targets)
            {
                if (target is ISwitchTarget switchTarget) switchTarget.SetActive(pressed);
            }
        }

        public void Configure(MonoBehaviour[] newTargets, bool isOneShot, bool revert)
        {
            targets = newTargets;
            oneShot = isOneShot;
            revertOnExit = revert;
        }
    }
}

