using System.Text;
using UnityEditor;
using UnityEngine;
using ThreeCup.GrayBox;

var sb = new StringBuilder();
Sprite sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/GrayBox/White4x4.png");
if (sprite == null) return "SPRITE_MISSING";

const string dir = "Assets/Prefabs/GrayBox";
const string mechDir = dir + "/Mechanisms";
if (!AssetDatabase.IsValidFolder(mechDir)) AssetDatabase.CreateFolder(dir, "Mechanisms");

GameObject Sprite1x1(Transform parent, string name, Color color, int order)
{
    var go = new GameObject(name);
    go.transform.SetParent(parent, false);
    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = color;
    sr.sortingOrder = order;
    return go;
}

string SavePrefab(GameObject root, string path)
