    float t0 = Time.time;
    float best = -99f;
    while (Time.time - t0 < 1.6f)
    {
        best = Mathf.Max(best, rb.position.y);
        yield return null;
    }

    sb.AppendLine($"[result] 落点 pos={rb.position} vel={rb.velocity} 最高点 y={best:0.00}");
    sb.AppendLine($"[verdict] {(rb.position.y < -5f ? "跳不过去（掉进坑里）" : "成功跨越")}");

    left.enabled = true;
    rb.WakeUp();
    rb.position = new Vector2(-7.3f, -2.55f);
    rb.velocity = Vector2.zero;

    Debug.Log("[GrayBox-GapTest]\n" + sb);
}

