var sb = new StringBuilder();
const string path = "Assets/Prefabs/GrayBox/L005.prefab";

var root = PrefabUtility.LoadPrefabContents(path);
if (root == null) return "LOAD_FAIL";

void Attach(string childName, string containerName, float width)
{
    var child = root.transform.Find(childName);
    if (child == null) { sb.AppendLine(childName + " MISSING"); return; }

    var container = root.transform.Find(containerName);
    if (container != null && child.parent != container)
    {
        var worldPos = child.position;
        child.SetParent(container, true);
        child.position = worldPos;
    }

    if (width > 0f)
    {
        var s = child.localScale;
        child.localScale = new Vector3(width, s.y, s.z);
    }

    float half = child.localScale.x * 0.5f;
    sb.AppendLine($"{childName}: parent={child.parent.name} x=[{child.position.x - half:0.00},{child.position.x + half:0.00}]");
}

Attach("Bridge_Left", "Blocks", 3.7f);
Attach("Bridge_Right", "Blocks", 3.7f);
