    float t0 = Time.time;
    float minX = 99f;
    int tick = 0;
    while (Time.time - t0 < 2.0f)
    {
        minX = Mathf.Min(minX, rb.position.x);
        if (tick++ % 20 == 0)
            sb.AppendLine($"  t={Time.time - t0:0.00} pos=({rb.position.x:0.00},{rb.position.y:0.00}) grounded={left.Grounded}");
        yield return null;
    }

    sb.AppendLine($"[结果] 最左 x={minX:0.00} 最终 pos=({rb.position.x:0.00},{rb.position.y:0.00})");
    sb.AppendLine($"[判断] {(minX < -1.2f ? "越过了平台与桥的接缝 ✓" : "卡在接缝 ✗")}");

    so.FindProperty("debugInput").boolValue = false;
    so.ApplyModifiedPropertiesWithoutUndo();
    rb.position = new Vector2(-7.3f, -2.55f);
    rb.velocity = Vector2.zero;

    Debug.Log("[GrayBox-RealMotor]\n" + sb);
}

return Run();

