IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();
    var router = UnityEngine.Object.FindObjectOfType<InputRouter>();
    var rb = left.GetComponent<Rigidbody2D>();

    session.LoadIndex(4);
    yield return null;
    yield return new WaitForSeconds(0.8f);
    right.GetComponent<Rigidbody2D>().position = new Vector2(6.2f, -2.6f);
    yield return new WaitForSeconds(0.6f);

    var bb = GameObject.Find("Bridge_Left").GetComponent<Collider2D>().bounds;
    sb.AppendLine($"Bridge_Left x=[{bb.min.x:0.00},{bb.max.x:0.00}] 平台 -1.20..0，出生台 -8.00..-4.60");

    var so = new SerializedObject(router);
    so.FindProperty("debugInput").boolValue = true;

    // ---- A) 终点平台 -> 桥（用户报告的方向）----
    so.FindProperty("debugHorizontal").floatValue = -1f;
    so.ApplyModifiedPropertiesWithoutUndo();
    rb.position = new Vector2(-0.55f, -1.4f);
    rb.velocity = Vector2.zero;
    yield return new WaitForSeconds(0.3f);

    float minX = 99f;
    float t0 = Time.time;
    bool stalled = false;
    float lastX = rb.position.x;
    int sameCount = 0;
    while (Time.time - t0 < 1.6f)
    {
        minX = Mathf.Min(minX, rb.position.x);
        if (Mathf.Abs(rb.position.x - lastX) < 0.001f && rb.position.y > -5f) sameCount++;
        else sameCount = 0;
        if (sameCount > 40) stalled = true;
        lastX = rb.position.x;
        yield return null;
    }
    sb.AppendLine($"[A 终点->桥] 最左 x={minX:0.00} 最终 pos=({rb.position.x:0.00},{rb.position.y:0.00}) 卡住={stalled}");

    // ---- B) 从左平台边缘跳上桥，再走到终点 ----
    rb.position = new Vector2(-5.2f, -2.6f);
    rb.velocity = Vector2.zero;
    so.FindProperty("debugHorizontal").floatValue = 1f;
    so.ApplyModifiedPropertiesWithoutUndo();
    yield return new WaitForSeconds(0.4f);

    rb.velocity = new Vector2(5.5f, 10.5f);   // 模拟起跳
