using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using ThreeCup.GrayBox;

var sb = new StringBuilder();
const string dir = "Assets/Pictures/background/";
string bgLeftPath = dir + "L18_水彩笔刷_边缘斑驳_960x1080_01.png";
string bgRightPath = dir + "L18_水彩笔刷_边缘斑驳_960x1080_02.png";
string canvasPath = dir + "L18_水彩笔刷_空白画布_960x1080.png";

void Configure(string path, float ppu, TextureWrapMode wrap)
{
    var ti = AssetImporter.GetAtPath(path) as TextureImporter;
    if (ti == null) { sb.AppendLine("NON_TEXTURE " + path); return; }

    ti.textureType = TextureImporterType.Sprite;
    ti.spriteImportMode = SpriteImportMode.Single;
    ti.spritePixelsPerUnit = ppu;
    ti.spriteMeshType = SpriteMeshType.FullRect;
    ti.filterMode = FilterMode.Bilinear;
    ti.wrapMode = wrap;
    ti.mipmapEnabled = true;
    ti.textureCompression = TextureImporterCompression.Uncompressed;
    ti.alphaIsTransparency = true;
    ti.SaveAndReimport();
    sb.AppendLine($"{System.IO.Path.GetFileName(path)}: ppu={ppu} wrap={wrap}");
}

// 背景：960/8 = 120 -> 每张正好 8x9 世界单位
Configure(bgLeftPath, 120f, TextureWrapMode.Clamp);
// 遮蔽层：960 -> 1x1 世界单位，配合 transform 缩放 + _Tile 平铺
Configure(canvasPath, 960f, TextureWrapMode.Repeat);

var bgLeft = AssetDatabase.LoadAssetAtPath<Sprite>(bgLeftPath);
var bgRight = AssetDatabase.LoadAssetAtPath<Sprite>(bgRightPath);
var canvas = AssetDatabase.LoadAssetAtPath<Sprite>(canvasPath);
if (bgLeft == null || bgRight == null || canvas == null) return "SPRITE_LOAD_FAIL\n" + sb;

// ---------- 场景背景 ----------
var grayBox = GameObject.Find("GrayBox");
if (grayBox == null) return "GRAYBOX_MISSING";

var oldBackdrop = GameObject.Find("Backdrop");
if (oldBackdrop != null) UnityEngine.Object.DestroyImmediate(oldBackdrop);

var backdrop = new GameObject("Backdrop");
backdrop.transform.SetParent(grayBox.transform, false);

GameObject MakeBackdrop(string name, Sprite sprite, float x)
{
    var go = new GameObject(name);
    go.transform.SetParent(backdrop.transform, false);
    go.transform.localPosition = new Vector3(x, 0f, 0f);
    go.transform.localScale = Vector3.one;

    var sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.color = Color.white;
    sr.sortingOrder = -10;
    return go;
}

MakeBackdrop("Backdrop_Left", bgLeft, -4f);
MakeBackdrop("Backdrop_Right", bgRight, 4f);

// ---------- 遮蔽层换成空白画布 ----------
var fogGo = GameObject.Find("Fog");
var fogSr = fogGo.GetComponent<SpriteRenderer>();
fogSr.sprite = canvas;
fogSr.color = new Color(0.40f, 0.34f, 0.30f, 1f);

var mat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Art/GrayBox/VisionFog.mat");
if (mat == null) return "MATERIAL_MISSING";
mat.SetTexture("_MainTex", canvas);
// 雾面是 24x14，画布一格 8x9 -> 平铺 3 x 1.556，保持纸张比例不拉伸
mat.SetVector("_Tile", new Vector4(3f, 14f / 9f, 0f, 0f));
EditorUtility.SetDirty(mat);

AssetDatabase.SaveAssets();
EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
bool saved = EditorSceneManager.SaveScene(SceneManager.GetActiveScene());

sb.AppendLine($"scene saved={saved}");
foreach (var n in new[] { "Backdrop_Left", "Backdrop_Right" })
{
    var go = GameObject.Find(n);
    var sr = go.GetComponent<SpriteRenderer>();
    var b = sr.bounds;
    sb.AppendLine($"{n}: sprite={sr.sprite.name} size={b.size} center={b.center} order={sr.sortingOrder}");
}
sb.AppendLine($"Fog: sprite={fogSr.sprite.name} color={fogSr.color} scale={fogGo.transform.localScale}");
return sb.ToString();

