    Color b = Sample(tex, cam, -6.0f, 2.6f);
    float diff = Mathf.Abs(a.r - b.r) + Mathf.Abs(a.g - b.g) + Mathf.Abs(a.b - b.b);
    sb.AppendLine($"[纹理] 两点色差={diff:0.0000} (>0.002 说明在采样画布纹理，不是纯色)");

    RenderTexture.active = null; cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-Backdrop]\n" + sb);
