using System.IO;
using System.Text;
using UnityEngine;

var sb = new StringBuilder();

foreach (var path in new[] {
    "Assets/Pictures/characters/A_序列帧_1280x480.png",
    "Assets/Pictures/characters/B_序列帧_1280x480.png" })
{
    var bytes = File.ReadAllBytes(path);
    var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    tex.LoadImage(bytes);

    var px = tex.GetPixels32();
    int total = px.Length;
    int transparent = 0;
    int opaque = 0;
    int minA = 255, maxA = 0;
    foreach (var c in px)
    {
        if (c.a == 0) transparent++;
        else if (c.a == 255) opaque++;
        if (c.a < minA) minA = c.a;
        if (c.a > maxA) maxA = c.a;
    }

    sb.AppendLine($"{Path.GetFileName(path)}: {tex.width}x{tex.height} 透明像素={transparent * 100f / total:0.0}% 全不透明={opaque * 100f / total:0.0}% alpha范围={minA}..{maxA}");

    // 8 列 x 3 行，检查每格是否有内容（alpha>10）
    const int cols = 8, rows = 3;
    int w = tex.width / cols, h = tex.height / rows;
    for (int r = 0; r < rows; r++)
    {
        var line = new StringBuilder($"  row{r}: ");
        for (int c = 0; c < cols; c++)
        {
            int count = 0;
            for (int y = 0; y < h; y += 2)
                for (int x = 0; x < w; x += 2)
                {
                    // 图片坐标原点在左下
                    int py = tex.height - 1 - (r * h + y);
                    if (px[py * tex.width + c * w + x].a > 10) count++;
                }
            line.Append(count > 5 ? "#" : ".");
        }
        sb.AppendLine(line.ToString());
    }

    // 取一格中心附近的颜色，确认背景色
    int cx = w / 2, cy = tex.height - 1 - (h / 2);
    sb.AppendLine($"  第一格中心颜色 = {px[cy * tex.width + cx]}");

    UnityEngine.Object.DestroyImmediate(tex);
}

return sb.ToString();

