using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

var sb = new StringBuilder();
const string dir = "Assets/Pictures/characters/";

void Process(string srcName)
{
    var bytes = File.ReadAllBytes(dir + srcName);
    var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    tex.LoadImage(bytes);

    int W = tex.width, H = tex.height;
    var px = tex.GetPixels32();
    var outPx = new Color32[px.Length];

    float Lum(Color32 c) => c.r * 0.3f + c.g * 0.59f + c.b * 0.11f;

    for (int i = 0; i < px.Length; i++)
    {
        // 纸面 ~232，角色填充 ~192。用 205->225 的渐变保留水彩软边
        float lum = Lum(px[i]);
        float a = 1f - Mathf.SmoothStep(0f, 1f, Mathf.InverseLerp(205f, 225f, lum));
        var c = px[i];
        outPx[i] = new Color32(c.r, c.g, c.b, (byte)Mathf.RoundToInt(Mathf.Clamp01(a) * 255f));
    }

    var outTex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    outTex.SetPixels32(outPx);
    outTex.Apply();

    string outPath = dir + Path.GetFileNameWithoutExtension(srcName) + "_alpha.png";
    File.WriteAllBytes(outPath, outTex.EncodeToPNG());
    AssetDatabase.ImportAsset(outPath);

    UnityEngine.Object.DestroyImmediate(tex);
    UnityEngine.Object.DestroyImmediate(outTex);

    // 测量每行每帧的内容 bbox（图片坐标原点左下）
    const int cols = 8, rows = 3;
    int cw = W / cols, ch = H / rows;
    sb.AppendLine($"=== {Path.GetFileName(outPath)} ===");
    for (int r = 0; r < rows; r++)
    {
        var line = new StringBuilder($"  row{r}: ");
        for (int c = 0; c < cols; c++)
        {
            int minX = 9999, maxX = -1, minY = 9999, maxY = -1, n = 0;
            for (int y = 0; y < ch; y++)
            {
                int py = H - 1 - (r * ch + y);
                for (int x = 0; x < cw; x++)
                {
                    if (outPx[py * W + c * cw + x].a < 40) continue;
                    n++;
                    if (x < minX) minX = x;
                    if (x > maxX) maxX = x;
                    if (y < minY) minY = y;
                    if (y > maxY) maxY = y;
                }
            }
            line.Append(n < 100 ? "[空] " : $"[x{minX}-{maxX} y{minY}-{maxY}] ");
        }
        sb.AppendLine(line.ToString());
    }
}

