using System.Collections.Generic;
using System.Text;
using UnityEditor;
using UnityEngine;
using ThreeCup.GrayBox;

var sb = new StringBuilder();
const string dir = "Assets/Pictures/characters/";

// ---- 重新切图：轴心落在碰撞盒中心，这样 SpriteRenderer 可以继续挂在角色根节点 ----
void Reslice(string fileName, string prefix, float ppu, float feetY, float colliderHalfHeight)
{
    string path = dir + fileName;
    var ti = AssetImporter.GetAtPath(path) as TextureImporter;
    if (ti == null) { sb.AppendLine("NOT_TEXTURE " + path); return; }

    const int cell = 160;
    const int height = 480;
    float pivotY = (feetY - colliderHalfHeight * ppu) / cell;

    ti.textureType = TextureImporterType.Sprite;
    ti.spriteImportMode = SpriteImportMode.Multiple;
    ti.spritePixelsPerUnit = ppu;
    ti.filterMode = FilterMode.Bilinear;
    ti.textureCompression = TextureImporterCompression.Uncompressed;
    ti.alphaIsTransparency = true;

    var metas = new List<SpriteMetaData>();
    void AddRow(int row, string tag, int count)
    {
        for (int c = 0; c < count; c++)
            metas.Add(new SpriteMetaData
            {
                name = $"{prefix}_{tag}_{c}",
                rect = new Rect(c * cell, height - (row + 1) * cell, cell, cell),
                alignment = (int)SpriteAlignment.Custom,
                pivot = new Vector2(0.5f, pivotY),
                border = Vector4.zero
            });
    }

    AddRow(0, "idle", 6);
    AddRow(1, "walk", 8);
    AddRow(2, "jump", 5);

    ti.spritesheet = metas.ToArray();
    ti.SaveAndReimport();
    sb.AppendLine($"{prefix}: ppu={ppu} pivotY={pivotY:0.000}");
}

Reslice("A_序列帧_1280x480_alpha.png", "A", 95f, 127f, 0.4f);
Reslice("B_序列帧_1280x480_alpha.png", "B", 71f, 126f, 0.4f);

AssetDatabase.Refresh();

Sprite[] LoadFrames(string path, string prefix, string tag, int count)
{
    var dict = new Dictionary<string, Sprite>();
    foreach (var o in AssetDatabase.LoadAllAssetsAtPath(path))
        if (o is Sprite s) dict[s.name] = s;

    var arr = new Sprite[count];
    for (int i = 0; i < count; i++)
    {
        dict.TryGetValue($"{prefix}_{tag}_{i}", out arr[i]);
        if (arr[i] == null) sb.AppendLine($"MISSING {prefix}_{tag}_{i}");
    }
    return arr;
}

void Wire(string prefabPath, string sheetPath, string prefix)
{
    var root = PrefabUtility.LoadPrefabContents(prefabPath);
    if (root == null) { sb.AppendLine("PREFAB_FAIL " + prefabPath); return; }

    var sr = root.GetComponent<SpriteRenderer>();
    var idle = LoadFrames(sheetPath, prefix, "idle", 6);
    var walk = LoadFrames(sheetPath, prefix, "walk", 8);
    var jump = LoadFrames(sheetPath, prefix, "jump", 5);

    sr.color = Color.white;
    sr.sprite = idle[0];

    var anim = root.GetComponent<PlayerSpriteAnimator>();
    if (anim == null) anim = root.AddComponent<PlayerSpriteAnimator>();

    var so = new SerializedObject(anim);
    so.FindProperty("target").objectReferenceValue = sr;

    void Fill(string field, Sprite[] arr)
    {
        var p = so.FindProperty(field);
        p.arraySize = arr.Length;
        for (int i = 0; i < arr.Length; i++) p.GetArrayElementAtIndex(i).objectReferenceValue = arr[i];
    }

    Fill("idle", idle);
    Fill("walk", walk);
    Fill("jump", jump);
    so.ApplyModifiedPropertiesWithoutUndo();

    PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
    PrefabUtility.UnloadPrefabContents(root);
    sb.AppendLine($"{prefabPath}: idle={idle.Length} walk={walk.Length} jump={jump.Length} sprite={idle[0].name}");
}

Wire("Assets/Prefabs/GrayBox/Player/Player_Left.prefab", dir + "A_序列帧_1280x480_alpha.png", "A");
Wire("Assets/Prefabs/GrayBox/Player/Player_Right.prefab", dir + "B_序列帧_1280x480_alpha.png", "B");

AssetDatabase.SaveAssets();
return sb.ToString();

using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

Color Sample(Texture2D t, Camera c, float x, float y)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(x, y, 0f));
    int px = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int py = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(px, py);
}

IEnumerator Run()
{
    var sb = new StringBuilder();
    var leftGo = GameObject.Find("Player_Left");
    var left = leftGo.GetComponent<PlayerMotor2D>();
    var sr = leftGo.GetComponent<SpriteRenderer>();
    var rb = leftGo.GetComponent<Rigidbody2D>();

    yield return new WaitForSeconds(1.0f);
    sb.AppendLine($"[初始] sprite={sr.sprite.name} color={sr.color} pos={leftGo.transform.position} grounded={left.Grounded}");

    // ---- 待机循环 ----
    var seen = new StringBuilder();
    string last = "";
    float t0 = Time.time;
    while (Time.time - t0 < 1.2f)
    {
        if (sr.sprite.name != last) { last = sr.sprite.name; seen.Append(last).Append(' '); }
        yield return null;
    }
    sb.AppendLine($"[待机] 帧序列: {seen}");

    // ---- 行走（关闭 motor 避免被输入清零）----
    left.enabled = false;
    rb.velocity = new Vector2(5f, 0f);
    yield return new WaitForSeconds(0.3f);
    seen.Clear(); last = "";
    t0 = Time.time;
    while (Time.time - t0 < 1.0f)
    {
        rb.velocity = new Vector2(5f, rb.velocity.y);
        if (sr.sprite.name != last) { last = sr.sprite.name; seen.Append(last).Append(' '); }
        yield return null;
    }
    sb.AppendLine($"[行走] 帧序列: {seen}");

    // ---- 跳跃：给一个起跳速度 ----
    rb.velocity = Vector2.zero;
