using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var leftGo = GameObject.Find("Player_Left");
    var rightGo = GameObject.Find("Player_Right");
    if (leftGo == null || rightGo == null) { Debug.Log("[GrayBox-Anim3] player missing"); yield break; }

    var sr = leftGo.GetComponent<SpriteRenderer>();
    var rb = leftGo.GetComponent<Rigidbody2D>();
    var srR = rightGo.GetComponent<SpriteRenderer>();

    yield return new WaitForSeconds(0.6f);
    sb.AppendLine($"[A] sprite={sr.sprite.name} flip={(sr.flipX ? "L" : "R")} size={sr.bounds.size}");
    sb.AppendLine($"[B] sprite={srR.sprite.name} flip={(srR.flipX ? "L" : "R")} size={srR.bounds.size}");

    // 跳跃：只给垂直速度，不需要输入
    rb.position = new Vector2(-6.0f, -2.55f);
    yield return new WaitForSeconds(0.2f);
    rb.velocity = new Vector2(0f, 10.5f);

    var seq = new StringBuilder();
    string last = "";
    float t0 = Time.time;
    while (Time.time - t0 < 1.3f)
    {
        string now = sr.sprite.name;
        if (now != last) { last = now; seq.Append(now).Append("  "); }
        yield return null;
    }
    sb.AppendLine($"[跳跃帧序] {seq}");

    Debug.Log("[GrayBox-Anim3]\n" + sb);
}

return Run();

