IEnumerator Run()
{
    var sb = new StringBuilder();
    var cam = Camera.main;
    var leftGo = GameObject.Find("Player_Left");
    var sr = leftGo.GetComponent<SpriteRenderer>();

    yield return new WaitForSeconds(0.8f);
    float px = leftGo.transform.position.x;
    float feetY = leftGo.transform.position.y - 0.4f;
    sb.AppendLine($"角色 x={px:0.00} 中心 y={leftGo.transform.position.y:0.00} 脚底 y={feetY:0.00} 平台顶 y=-3.00");

    const int W = 960, H = 540;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();

    Color Sample(float x, float y)
    {
        Vector3 vp = cam.WorldToViewportPoint(new Vector3(x, y, 0f));
        int ix = Mathf.Clamp(Mathf.RoundToInt(vp.x * W), 0, W - 1);
        int iy = Mathf.Clamp(Mathf.RoundToInt(vp.y * H), 0, H - 1);
        return tex.GetPixel(ix, iy);
    }

    // 竖直扫描，找出角色（暖色）占据的范围
    float top = -99f, bottom = 99f;
    for (float y = -4.2f; y <= 0.5f; y += 0.0083f)
    {
        var c = Sample(px, y);
        bool warm = c.r > c.b + 0.06f && c.r > 0.55f;   // 角色偏暖，平台/背景偏冷或极亮
        if (!warm) continue;
        if (y > top) top = y;
        if (y < bottom) bottom = y;
    }

    sb.AppendLine($"角色在屏幕上占 y={bottom:0.00}..{top:0.00}  高度={top - bottom:0.00} 世界单位 = {(top - bottom) * 120f:0} px");
    sb.AppendLine($"脚底实测={bottom:0.00}（应与平台顶 -3.00 对齐）");
    sb.AppendLine($"脚下方一点 y=-3.05 颜色={Sample(px, -3.05f)}  (平台色 0.42/0.45/0.52)");

    RenderTexture.active = null; cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-Size]\n" + sb);
}

return Run();

