IEnumerator Run()
{
    var sb = new StringBuilder();
    var cam = Camera.main;
    var leftGo = GameObject.Find("Player_Left");
    var sr = leftGo.GetComponent<SpriteRenderer>();
    yield return new WaitForSeconds(0.8f);

    float px = leftGo.transform.position.x;
    sb.AppendLine($"角色中心=({px:0.00},{leftGo.transform.position.y:0.00})  脚底应为 {leftGo.transform.position.y - 0.4f:0.00}  平台顶 -3.00");

    // 只打开角色自己的渲染器，其余全部临时关闭，避免背景/高亮干扰测量
    var all = UnityEngine.Object.FindObjectsOfType<SpriteRenderer>();
    var saved = new System.Collections.Generic.Dictionary<SpriteRenderer, bool>();
    foreach (var r in all) { saved[r] = r.enabled; if (r != sr) r.enabled = false; }

    const int W = 960, H = 540;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();

    foreach (var kv in saved) if (kv.Key != null) kv.Key.enabled = kv.Value;

    Color Sample(float x, float y)
    {
        Vector3 vp = cam.WorldToViewportPoint(new Vector3(x, y, 0f));
        int ix = Mathf.Clamp(Mathf.RoundToInt(vp.x * W), 0, W - 1);
        int iy = Mathf.Clamp(Mathf.RoundToInt(vp.y * H), 0, H - 1);
        return tex.GetPixel(ix, iy);
    }

    var clear = cam.backgroundColor;
    float top = -99f, bottom = 99f, leftB = 99f, rightB = -99f;
    for (float y = -4.0f; y <= 0.5f; y += 1f / 120f)
        for (float x = px - 1.2f; x <= px + 1.2f; x += 1f / 120f)
        {
            var c = Sample(x, y);
            if (Mathf.Abs(c.r - clear.r) + Mathf.Abs(c.g - clear.g) + Mathf.Abs(c.b - clear.b) < 0.02f) continue;
            if (y > top) top = y;
            if (y < bottom) bottom = y;
            if (x < leftB) leftB = x;
            if (x > rightB) rightB = x;
        }

    sb.AppendLine($"实测角色范围: y={bottom:0.00}..{top:0.00} (高 {top - bottom:0.00})  x={leftB:0.00}..{rightB:0.00} (宽 {rightB - leftB:0.00})");
    sb.AppendLine($"脚底 {bottom:0.00} vs 平台顶 -3.00 -> 偏差 {bottom + 3f:+0.00;-0.00}");

    RenderTexture.active = null; cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-Size2]\n" + sb);
}

return Run();

