// 内容 bbox 之前是从格子【顶部】往下量的，换回距格子底部的像素后重新算轴心：
//   轴心 = 脚底像素 + (0.4 世界单位 / 节点缩放0.8) * ppu
void Reslice(string file, string prefix, float ppu, float feetFromBottomPx, float centerX)
{
    var ti = AssetImporter.GetAtPath(dir + file) as TextureImporter;
    if (ti == null) { sb.AppendLine("NOT_TEXTURE " + file); return; }

    const int cell = 160;
    const int height = 480;
    float pivotYpx = feetFromBottomPx + 0.4f / 0.8f * ppu;   // 脚底在轴心下方 0.5 精灵单位
    float pivotY = pivotYpx / cell;
    float pivotX = centerX / cell;

    ti.spriteImportMode = SpriteImportMode.Multiple;

    var metas = new List<SpriteMetaData>();
    void AddRow(int row, string tag, int count)
    {
        for (int c = 0; c < count; c++)
            metas.Add(new SpriteMetaData
            {
                name = $"{prefix}_{tag}_{c}",
                rect = new Rect(c * cell, height - (row + 1) * cell, cell, cell),
                alignment = (int)SpriteAlignment.Custom,
                pivot = new Vector2(pivotX, pivotY),
                border = Vector4.zero
            });
    }

    AddRow(0, "idle", 6);
    AddRow(1, "walk", 8);
    AddRow(2, "jump", 5);

    ti.spritesheet = metas.ToArray();
    ti.SaveAndReimport();
    sb.AppendLine($"{prefix}: ppu={ppu} 脚底={feetFromBottomPx}px 轴心={pivotYpx:0.0}px ({pivotY:0.000})");
}

