using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using UnityEditor;
using UnityEngine;

var sb = new StringBuilder();

void FixMeta(string path, float pivotX, float pivotY)
{
    string metaPath = path + ".meta";
    var text = File.ReadAllText(metaPath);

    var before = Regex.Matches(text, @"pivot: \{x: [0-9.]+, y: [0-9.]+\}").Count;
    text = Regex.Replace(text, @"pivot: \{x: [0-9.]+, y: [0-9.]+\}",
        $"pivot: {{x: {pivotX.ToString("0.#####", System.Globalization.CultureInfo.InvariantCulture)}, y: {pivotY.ToString("0.#####", System.Globalization.CultureInfo.InvariantCulture)}}}");

    File.WriteAllText(metaPath, text);
    AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceUpdate);

    sb.AppendLine($"{Path.GetFileName(path)}: 替换 {before} 处 -> pivot=({pivotX:0.0000},{pivotY:0.0000})");
}

