    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    session.LoadIndex(0);
    yield return new WaitForSeconds(1.0f);

    var leftGo = GameObject.Find("Player_Left");
    var sr = leftGo.GetComponent<SpriteRenderer>();
    float px = leftGo.transform.position.x;

    var all = UnityEngine.Object.FindObjectsOfType<SpriteRenderer>();
    var saved = new System.Collections.Generic.Dictionary<SpriteRenderer, bool>();
    foreach (var r in all) { saved[r] = r.enabled; if (r != sr) r.enabled = false; }

    const int W = 960, H = 540;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);

    void Grab()
    {
        var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
        cam.targetTexture = rt;
        cam.Render();
        RenderTexture.active = rt;
        tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
        tex.Apply();
        RenderTexture.active = null;
        cam.targetTexture = null;
        rt.Release();
        UnityEngine.Object.Destroy(rt);
    }

    Color Sample(float x, float y)
    {
        Vector3 vp = cam.WorldToViewportPoint(new Vector3(x, y, 0f));
        int ix = Mathf.Clamp(Mathf.RoundToInt(vp.x * W), 0, W - 1);
        int iy = Mathf.Clamp(Mathf.RoundToInt(vp.y * H), 0, H - 1);
        return tex.GetPixel(ix, iy);
    }

    var clear = cam.backgroundColor;
    void Measure(out float bottom, out float l, out float r)
    {
        bottom = 99f; l = 99f; r = -99f;
        for (float y = -4f; y <= 0.5f; y += 1f / 240f)
            for (float x = px - 1.2f; x <= px + 1.2f; x += 1f / 240f)
            {
                var c = Sample(x, y);
                if (Mathf.Abs(c.r - clear.r) + Mathf.Abs(c.g - clear.g) + Mathf.Abs(c.b - clear.b) < 0.1f) continue;
                if (y < bottom) bottom = y;
                if (x < l) l = x;
                if (x > r) r = x;
            }
    }

    yield return new WaitForEndOfFrame();
    sr.flipX = false;
    yield return new WaitForEndOfFrame();
    Grab();
    Measure(out float b1, out float l1, out float r1);
    sb.AppendLine($"[朝右] 脚底={b1:0.000} (相对平台顶 {b1 + 3f:+0.000;-0.000}) 横向=[{l1 - px:+0.000;-0.000},{r1 - px:+0.000;-0.000}] 中心={(l1 + r1) * 0.5f - px:+0.000;-0.000}");

    sr.flipX = true;
    yield return new WaitForEndOfFrame();
    Grab();
    Measure(out float b2, out float l2, out float r2);
    sb.AppendLine($"[朝左] 脚底={b2:0.000} 横向=[{l2 - px:+0.000;-0.000},{r2 - px:+0.000;-0.000}] 中心={(l2 + r2) * 0.5f - px:+0.000;-0.000}");
