var sb = new StringBuilder();
const string pics = "Assets/Pictures/";
const string mechDir = "Assets/Prefabs/GrayBox/Mechanisms/";

Sprite[] ImportFrames(string folder, string prefix, int count, float ppu)
{
    var arr = new Sprite[count];
    for (int i = 0; i < count; i++)
    {
        string path = $"{pics}{folder}/{prefix}_{i:00}.png";
        var ti = AssetImporter.GetAtPath(path) as TextureImporter;
        if (ti == null) { sb.AppendLine("NOT_TEXTURE " + path); continue; }
        ti.textureType = TextureImporterType.Sprite;
        ti.spriteImportMode = SpriteImportMode.Single;
        ti.spritePixelsPerUnit = ppu;
        ti.filterMode = FilterMode.Bilinear;
        ti.textureCompression = TextureImporterCompression.Uncompressed;
        ti.mipmapEnabled = false;
        ti.alphaIsTransparency = true;
        ti.SaveAndReimport();

        arr[i] = AssetDatabase.LoadAssetAtPath<Sprite>(path);
        if (arr[i] == null) sb.AppendLine("SPRITE_MISSING " + path);
    }
    return arr;
}

var stainFrames = ImportFrames("05_水痕_死亡反馈", "05_水痕_死亡反馈", 8, 290f);
var cleanFrames = ImportFrames("06_清洁晕_特效", "06_清洁晕_特效", 8, 200f);

GameObject BuildEffect(string prefabPath, Sprite[] frames, float fps, string name)
{
    var root = new GameObject(name);
    var sr = root.AddComponent<SpriteRenderer>();
    sr.sprite = frames[0];
    sr.color = Color.white;
    sr.sortingOrder = GrayBoxSorting.Hint;

    var fx = root.AddComponent<SpriteFrameEffect>();
    var so = new SerializedObject(fx);
    so.FindProperty("target").objectReferenceValue = sr;
    so.FindProperty("fps").floatValue = fps;
    so.FindProperty("loop").boolValue = false;
    so.FindProperty("destroyOnFinish").boolValue = true;
    var framesProp = so.FindProperty("frames");
    framesProp.arraySize = frames.Length;
    for (int i = 0; i < frames.Length; i++) framesProp.GetArrayElementAtIndex(i).objectReferenceValue = frames[i];
    so.ApplyModifiedPropertiesWithoutUndo();

    var prefab = PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
    UnityEngine.Object.DestroyImmediate(root);
    sb.AppendLine($"{prefabPath}: frames={frames.Length} fps={fps} ok={prefab != null}");
    return prefab;
}

var stainPrefab = BuildEffect(mechDir + "Effect_WaterStain.prefab", stainFrames, 12f, "Effect_WaterStain");
