foreach (var dir in new[] { "Assets/Tiles", "Assets/Pictures/污渍" })
{
    sb.AppendLine("=== " + dir + " ===");
    foreach (var path in Directory.GetFiles(dir, "*.png"))
    {
        var norm = path.Replace('\\', '/');
        var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
        tex.LoadImage(File.ReadAllBytes(norm));
        var px = tex.GetPixels32();

        int transparent = 0;
        int minX = 9999, maxX = -1, minY = 9999, maxY = -1;
        for (int y = 0; y < tex.height; y++)
            for (int x = 0; x < tex.width; x++)
            {
                var c = px[y * tex.width + x];
                if (c.a < 20) { transparent++; continue; }
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }

        var ti = AssetImporter.GetAtPath(norm) as TextureImporter;
        sb.AppendLine($"  {Path.GetFileName(norm)}: {tex.width}x{tex.height} 透明={transparent * 100f / px.Length:0}% 内容=x[{minX},{maxX}] y[{minY},{maxY}] ppu={(ti != null ? ti.spritePixelsPerUnit.ToString() : "?")} type={(ti != null ? ti.textureType.ToString() : "?")}");

        UnityEngine.Object.DestroyImmediate(tex);
    }
}
return sb.ToString();

using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

var sb = new StringBuilder();

// ---------- Tiles：裁到内容方形，PPU 让每块正好 0.8 世界单位（与平台厚度一致）----------
foreach (var path in Directory.GetFiles("Assets/Tiles", "*.png"))
{
    var norm = path.Replace('\\', '/');
    var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    tex.LoadImage(File.ReadAllBytes(norm));
    var px = tex.GetPixels32();

    int minX = 9999, maxX = -1, minY = 9999, maxY = -1;
    for (int y = 0; y < tex.height; y++)
        for (int x = 0; x < tex.width; x++)
        {
            if (px[y * tex.width + x].a < 20) continue;
            if (x < minX) minX = x; if (x > maxX) maxX = x;
            if (y < minY) minY = y; if (y > maxY) maxY = y;
        }

    int cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
    int side = Mathf.Max(maxX - minX, maxY - minY) + 48;   // 留一点边，避免切掉柔和边缘
    int rx = Mathf.Clamp(cx - side / 2, 0, tex.width - side);
    int ry = Mathf.Clamp(cy - side / 2, 0, tex.height - side);

    var ti = AssetImporter.GetAtPath(norm) as TextureImporter;
    ti.textureType = TextureImporterType.Sprite;
    ti.spriteImportMode = SpriteImportMode.Multiple;
    ti.spritePixelsPerUnit = side / 0.8f;
    ti.filterMode = FilterMode.Bilinear;
    ti.textureCompression = TextureImporterCompression.Uncompressed;
    ti.alphaIsTransparency = true;
    ti.spritesheet = new[]
    {
        new SpriteMetaData
        {
            name = Path.GetFileNameWithoutExtension(norm),
            rect = new Rect(rx, ry, side, side),
            alignment = (int)SpriteAlignment.Center,
            pivot = new Vector2(0.5f, 0.5f)
        }
    };
    ti.SaveAndReimport();

    sb.AppendLine($"Tile {Path.GetFileName(norm)}: 内容 {maxX - minX + 1}x{maxY - minY + 1} 裁切 {side}px ppu={side / 0.8f:0} 世界=0.80");
    UnityEngine.Object.DestroyImmediate(tex);
}

