// 各关卡里的 Plat_* 全部转成 Tiled
void ConvertLevel(string prefabPath)
{
    var root = PrefabUtility.LoadPrefabContents(prefabPath);
    if (root == null) { sb.AppendLine(prefabPath + " LOAD_FAIL"); return; }

    var terrain = root.transform.Find("Terrain");
    if (terrain == null) { sb.AppendLine(prefabPath + " 无 Terrain"); PrefabUtility.UnloadPrefabContents(root); return; }

    int count = 0;
    foreach (Transform child in terrain)
    {
        if (!child.name.StartsWith("Plat_")) continue;

        var scale = child.localScale;
        float w = Mathf.Abs(scale.x);
        float h = Mathf.Abs(scale.y);

        var sr = child.GetComponent<SpriteRenderer>();
        var col = child.GetComponent<BoxCollider2D>();

        sr.sprite = tileSprite;
        sr.color = Color.white;
        sr.drawMode = SpriteDrawMode.Tiled;
        sr.tileMode = SpriteTileMode.Continuous;
        sr.size = new Vector2(w, h);
        sr.sortingOrder = GrayBoxSorting.Terrain;

        if (col != null) col.size = new Vector2(w, h);
        child.localScale = Vector3.one;

        count++;
        sb.AppendLine($"  {prefabPath.Replace("Assets/Prefabs/GrayBox/", "")} {child.name}: {w:0.00} x {h:0.00}");
    }

    PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
    PrefabUtility.UnloadPrefabContents(root);
    sb.AppendLine($"{prefabPath}: 转换 {count} 块平台");
}

