    string p = "Assets/Prefabs/GrayBox/Mechanisms/" + prefabName + ".prefab";
    var root = PrefabUtility.LoadPrefabContents(p);
    if (root == null) { sb.AppendLine(p + " LOAD_FAIL"); return; }

    // 去掉根上的旧色块
    var rootSr = root.GetComponent<SpriteRenderer>();
    if (rootSr != null) UnityEngine.Object.DestroyImmediate(rootSr);

    var old = root.transform.Find("Visual");
    if (old != null) UnityEngine.Object.DestroyImmediate(old.gameObject);

    var visual = new GameObject("Visual");
    visual.transform.SetParent(root.transform, false);
    var sr = visual.AddComponent<SpriteRenderer>();
    sr.sprite = blot;
    sr.color = Color.white;
    sr.sortingOrder = GrayBoxSorting.Mechanism;

    // 触发体高 1.8，中心在根上 -> 底部 = 根 -0.9；让污渍底边贴住它
    float h = blot.bounds.size.y;
    visual.transform.localPosition = new Vector3(0f, -0.9f + h * 0.5f, 0f);
    visual.transform.localScale = Vector3.one;

    PrefabUtility.SaveAsPrefabAsset(root, p);
    PrefabUtility.UnloadPrefabContents(root);
    sb.AppendLine($"{prefabName}: blot={blot.name} 尺寸={blot.bounds.size} localY={-0.9f + h * 0.5f:0.000}");
