    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();
    foreach (var r in hide) if (r != null) r.enabled = true;

    Color Sample(float x, float y)
    {
        Vector3 vp = cam.WorldToViewportPoint(new Vector3(x, y, 0f));
        int ix = Mathf.Clamp(Mathf.RoundToInt(vp.x * W), 0, W - 1);
        int iy = Mathf.Clamp(Mathf.RoundToInt(vp.y * H), 0, H - 1);
        return tex.GetPixel(ix, iy);
    }

    var clear = cam.backgroundColor;
    bool On(float x, float y)
    {
        var c = Sample(x, y);
        return Mathf.Abs(c.r - clear.r) + Mathf.Abs(c.g - clear.g) + Mathf.Abs(c.b - clear.b) > 0.12f;
    }

    float top = -99f, bottom = 99f;
    for (float y = -5f; y <= 0f; y += 1f / 240f) if (On(-6f, y)) { if (y > top) top = y; if (y < bottom) bottom = y; }
    sb.AppendLine($"[平台] y={bottom:0.00}..{top:0.00}  碰撞面 -3.00 -> 视觉偏差 {top + 3f:+0.000;-0.000}");

    float l = 99f, r2 = -99f;
    for (float x = -9f; x <= -3f; x += 1f / 240f) if (On(x, -3.4f)) { if (x < l) l = x; if (x > r2) r2 = x; }
    sb.AppendLine($"[平台] x={l:0.00}..{r2:0.00}");

    RenderTexture.active = null; cam.targetTexture = null;
    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);

    Debug.Log("[GrayBox-TileFix]\n" + sb);
}

