using System.Text;
using UnityEditor;
using UnityEngine;
using ThreeCup.GrayBox;

var sb = new StringBuilder();

// ---------- 材质 ----------
const string matPath = "Assets/Art/GrayBox/StainDissolve.mat";
var shader = Shader.Find("GrayBox/StainDissolve");
if (shader == null) return "SHADER_NOT_FOUND";

var mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
mat.shader = shader;
mat.SetColor("_Color", Color.white);
mat.SetFloat("_Softness", 0.22f);
EditorUtility.SetDirty(mat);
sb.AppendLine($"材质 {matPath} shader={mat.shader.name}");

// ---------- 终点预制体 ----------
foreach (var n in new[] { "Goal_Left", "Goal_Right" })
{
    string p = "Assets/Prefabs/GrayBox/Mechanisms/" + n + ".prefab";
    var root = PrefabUtility.LoadPrefabContents(p);
    var visual = root.transform.Find("Visual");
    if (visual == null) { sb.AppendLine(n + " 无 Visual"); PrefabUtility.UnloadPrefabContents(root); continue; }

    var sr = visual.GetComponent<SpriteRenderer>();
    sr.sortingOrder = GrayBoxSorting.Hint;     // 显示在遮蔽层之上
    sr.sharedMaterial = mat;
    sr.color = Color.white;

    var dissolve = visual.GetComponent<StainDissolve>();
    if (dissolve == null) dissolve = visual.gameObject.AddComponent<StainDissolve>();

    var so = new SerializedObject(dissolve);
    so.FindProperty("target").objectReferenceValue = sr;
    so.ApplyModifiedPropertiesWithoutUndo();

    PrefabUtility.SaveAsPrefabAsset(root, p);
    PrefabUtility.UnloadPrefabContents(root);
    sb.AppendLine($"{n}: 排序={GrayBoxSorting.Hint} 材质={mat.name} 溶解组件=已挂");
}

// ---------- 删除不再使用的清洁晕帧动画 ----------
AssetDatabase.DeleteAsset("Assets/Prefabs/GrayBox/Mechanisms/Effect_CleanBurst.prefab");
sb.AppendLine("已删除 Effect_CleanBurst.prefab");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return sb.ToString();

