Vector4 Pack(int index)
{
    if (windows == null || index >= windows.Length || windows[index] == null) return Disabled;

    var window = windows[index];
    Vector2 center = window.ResolveCenter();
    Vector2 half = window.Size * 0.5f;

    // 视窗不能越过中间的隔离墙：右侧窗口裁掉中线左边，左侧窗口裁掉右边，
    // 否则视窗贴到边界时会漏出对侧一小条地形。
    float minX = center.x - half.x;
    float maxX = center.x + half.x;

    if (center.x >= splitX) minX = Mathf.Max(minX, splitX);
    else maxX = Mathf.Min(maxX, splitX);

    float width = maxX - minX;
    if (width <= 0.001f) return Disabled;

    center.x = (minX + maxX) * 0.5f;
    half.x = width * 0.5f;

    return new Vector4(center.x, center.y, Mathf.Max(half.x, 0.001f), Mathf.Max(half.y, 0.001f));
}

