using System.Collections;
using System.Text;
using UnityEngine;
using ThreeCup.GrayBox;

Color Sample(Texture2D t, Camera c, float x, float y)
{
    Vector3 vp = c.WorldToViewportPoint(new Vector3(x, y, 0f));
    int ix = Mathf.Clamp(Mathf.RoundToInt(vp.x * t.width), 0, t.width - 1);
    int iy = Mathf.Clamp(Mathf.RoundToInt(vp.y * t.height), 0, t.height - 1);
    return t.GetPixel(ix, iy);
}

string Tag(Color c) => $"({c.r:0.00},{c.g:0.00},{c.b:0.00})";

IEnumerator Run()
{
    var sb = new StringBuilder();
    var cam = Camera.main;
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var left = GameObject.Find("Player_Left").GetComponent<PlayerMotor2D>();
    var right = GameObject.Find("Player_Right").GetComponent<PlayerMotor2D>();
    var lw = GameObject.Find("Window_OfLeftChar").GetComponent<VisionWindow>();

    session.LoadIndex(0);
    yield return new WaitForSeconds(0.8f);

    // 把左角色推到最左，让它的视窗贴到中线（视窗中心 = x+8）
    left.GetComponent<Rigidbody2D>().position = new Vector2(-7.5f, -2.6f);
    right.GetComponent<Rigidbody2D>().position = new Vector2(7.5f, -2.6f);
    yield return new WaitForSeconds(0.4f);

    Vector2 c0 = lw.ResolveCenter();
    sb.AppendLine($"左视窗中心={c0} 名义范围 x[{c0.x - 2:0.00},{c0.x + 2:0.00}]（裁剪后应为 [0.00,{c0.x + 2:0.00}]）");

    const int W = 960, H = 540;
    var rt = new RenderTexture(W, H, 24, RenderTextureFormat.ARGB32);
    cam.targetTexture = rt;
    yield return new WaitForEndOfFrame();
    RenderTexture.active = rt;
    var tex = new Texture2D(W, H, TextureFormat.RGBA32, false);
    tex.ReadPixels(new Rect(0, 0, W, H), 0, 0);
    tex.Apply();
    RenderTexture.active = null; cam.targetTexture = null;

    var fog = GameObject.Find("Fog").GetComponent<SpriteRenderer>().color;
    float y = c0.y;
    sb.AppendLine($"扫描同一水平线 y={y:0.00}：");
    foreach (float x in new[] { -1.6f, -0.8f, -0.4f, 0.3f, 0.8f, 1.5f })
        sb.AppendLine($"  x={x:+0.0;-0.0} = {Tag(Sample(tex, cam, x, y))}");

    sb.AppendLine($"参考：遮盖色={Tag(fog)}  背景≈(0.96,0.93,0.87)");

    UnityEngine.Object.Destroy(tex); rt.Release(); UnityEngine.Object.Destroy(rt);
    Debug.Log("[GrayBox-WindowClip]\n" + sb);
}

return Run();

